INSERT INTO `wp_options` VALUES (107, 'widget_block', 'a:10:{i:2;a:1:{s:7:\"content\";s:19:\"<!-- wp:search /-->\";}i:3;a:1:{s:7:\"content\";s:154:\"<!-- wp:group --><div class=\"wp-block-group\"><!-- wp:heading --><h2>近期文章</h2><!-- /wp:heading --><!-- wp:latest-posts /--></div><!-- /wp:group -->\";}i:4;a:1:{s:7:\"content\";s:224:\"<!-- wp:group --><div class=\"wp-block-group\"><!-- wp:heading --><h2>近期评论</h2><!-- /wp:heading --><!-- wp:latest-comments {\"displayAvatar\":false,\"displayDate\":false,\"displayExcerpt\":false} /--></div><!-- /wp:group -->\";}i:5;a:1:{s:7:\"content\";s:144:\"<!-- wp:group --><div class=\"wp-block-group\"><!-- wp:heading --><h2>归档</h2><!-- /wp:heading --><!-- wp:archives /--></div><!-- /wp:group -->\";}i:6;a:1:{s:7:\"content\";s:146:\"<!-- wp:group --><div class=\"wp-block-group\"><!-- wp:heading --><h2>分类</h2><!-- /wp:heading --><!-- wp:categories /--></div><!-- /wp:group -->\";}i:1;a:1:{s:7:\"content\";s:319:\"<!-- wp:image {\"id\":30,\"width\":\"150px\",\"height\":\"28px\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full is-resized\"><img src=\"https://hermes-fs.test/wp-content/uploads/2023/05/logo-light.svg\" alt=\"\" class=\"wp-image-30\" style=\"width:150px;height:28px\"/></figure>\n<!-- /wp:image -->\";}i:7;a:1:{s:7:\"content\";s:689:\"<!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"level\":3,\"className\":\"widget-title\",\"fontSize\":\"medium\"} -->\n<h3 class=\"wp-block-heading widget-title has-medium-font-size\" id=\"45647-hermiston-field-bruenberg-guinea\">45647 Hermiston Field Bruenberg, Guinea</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>Email:</strong> email@company.com<br><strong>Phone:</strong> +047-919-2363</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Aenean sed nibh a magna posuere tempor. Nunc faucibus pellentesque nunc in aliquet. Donec congue, nunc vel tempor congue, enim sapien lobortis.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\";}i:8;a:1:{s:7:\"content\";s:963:\"<!-- wp:blocksy/widgets-wrapper {\"heading\":\"Newsletter\",\"block\":\"blocksy/newsletter\",\"hasDescription\":true,\"description\":\"Enter your email address below to subscribe to our newsletter\",\"className\":\"wp-block-blocksy-widgets-wrapper\"} -->\n<!-- wp:heading {\"level\":3,\"className\":\"widget-title\",\"fontSize\":\"medium\"} -->\n<h3 class=\"wp-block-heading widget-title has-medium-font-size\" id=\"subscribe-to-newsletter-1\">Subscribe to newsletter</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"placeholder\":\"Description\"} -->\n<p>Saepe nulla quia. Corporis vero modi consectetur sequi nesciunt. Aut voluptate iusto sint ab aut. Iste quas sequi fuga nihil magnam nemo voluptas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:blocksy/newsletter {\"inputFontColor\":\"palette-color-3\",\"inputFontColorFocus\":\"palette-color-3\",\"lock\":{\"remove\":true},\"className\":\"wp-block-blocksy-newsletter\"} -->\n<div>Blocksy: Newsletter</div>\n<!-- /wp:blocksy/newsletter -->\n<!-- /wp:blocksy/widgets-wrapper -->\";}i:9;a:1:{s:7:\"content\";s:600:\"<!-- wp:blocksy/widgets-wrapper -->\n<!-- wp:blocksy/socials {\"socials\":[{\"id\":\"facebook\",\"enabled\":true},{\"id\":\"twitter\",\"enabled\":true},{\"id\":\"instagram\",\"enabled\":true},{\"id\":\"linkedin\",\"enabled\":true,\"icon_source\":\"default\",\"icon\":{\"icon\":\"blc blc-email\"},\"url_source\":\"default\",\"custom_url\":\"\",\"__id\":\"PRyZZboxp79LSIbZ1ppt3\"}],\"social_icons_size\":\"15\",\"items_spacing\":\"20\",\"initialColor\":\"palette-color-8\",\"borderColor\":\"palette-color-8\",\"borderHoverColor\":\"palette-color-1\",\"lock\":{\"remove\":true}} -->\n<div>Blocksy: Socials</div>\n<!-- /wp:blocksy/socials -->\n<!-- /wp:blocksy/widgets-wrapper -->\";}s:12:\"_multiwidget\";i:1;}', 'off');
