rgba(255, 255, 255, 0.8);\n}\n@media (max-width: 768px) {\n  .jf-floating-engineer-bar {\n    right: 12px;\n    bottom: 12px;\n    left: 12px;\n    flex-direction: row;\n  }\n  .jf-float-btn {\n    flex: 1;\n    justify-content: center;\n  }\n}\n</style>\n<!-- /wp:html -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->', 'Floating WhatsApp &amp; Spec Sheet Sticky Bar', '', 'inherit', 'closed', 'closed', '', '1851-autosave-v1', '', '', '2026-11-04 12:07:22', '2026-11-04 04:07:22', '', 1851, 'https://hermes-fs.test/?p=1854', 0, 'revision', '', 0);
