INSERT INTO `wp_posts` VALUES (1856, 1, '2026-11-04 12:09:31', '2026-11-04 04:09:31', '<!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"background\":\"#0f172a\",\"text\":\"#f8fafc\"},\"spacing\":{\"padding\":{\"top\":\"90px\",\"bottom\":\"90px\",\"left\":\"24px\",\"right\":\"24px\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1280px\"}} -->\n<div class=\"wp-block-group alignfull has-text-color has-background\" style=\"background-color:#0f172a;color:#f8fafc;padding-top:90px;padding-right:24px;padding-bottom:90px;padding-left:24px\">\n\n  <!-- wp:columns {\"verticalAlignment\":\"center\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"48px\",\"left\":\"48px\"}}}} -->\n  <div class=\"wp-block-columns are-vertically-aligned-center\">\n\n    <!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"60%\"} -->\n    <div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:60%\">\n      <!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"13px\",\"fontWeight\":\"700\",\"letterSpacing\":\"0.08em\",\"textTransform\":\"uppercase\"},\"color\":{\"text\":\"#38bdf8\"}}} -->\n      <p class=\"has-text-color\" style=\"color:#38bdf8;font-size:13px;font-weight:700;letter-spacing:0.08em;text-transform:uppercase\">INDUSTRIAL 3D FILAMENT EXTRUSION SYSTEMS | 15–25M TURNKEY LINES</p>\n      <!-- /wp:paragraph -->\n\n      <!-- wp:heading {\"level\":1,\"style\":{\"typography\":{\"fontSize\":\"44px\",\"lineHeight\":\"1.18\",\"fontWeight\":\"800\"},\"spacing\":{\"margin\":{\"top\":\"12px\",\"bottom\":\"20px\"}}}} -->\n      <h1 class=\"wp-block-heading\" style=\"margin-top:12px;margin-bottom:20px;font-size:44px;font-weight:800;line-height:1.18\">Engineered for ±0.02mm Diameter Precision. Built for 24/7 Industrial Filament Production.</h1>\n      <!-- /wp:heading -->\n\n      <!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"18px\",\"lineHeight\":\"1.65\"},\"color\":{\"text\":\"#cbd5e1\"}}} -->\n      <p class=\"has-text-color\" style=\"color:#cbd5e1;font-size:18px;line-height:1.65\">Stop losing margin to ovality, diameter drift, and tangled spools. We manufacture heavy-duty 15–25m filament extrusion lines integrating <strong>in-house CNC-machined screws</strong>, <strong>real-time laser-to-puller closed-loop control</strong>, and <strong>validated polymer processing recipes</strong>—from standard PLA/PETG to ultra-high-temp PEEK.</p>\n      <!-- /wp:paragraph -->\n\n      <!-- wp:buttons {\"style\":{\"spacing\":{\"margin\":{\"top\":\"32px\"}}}} -->\n      <div class=\"wp-block-buttons\" style=\"margin-top:32px\">\n        <!-- wp:button {\"style\":{\"color\":{\"background\":\"#ea580c\",\"text\":\"#ffffff\"},\"border\":{\"radius\":\"6px\"},\"typography\":{\"fontSize\":\"16px\",\"fontWeight\":\"600\"},\"spacing\":{\"padding\":{\"top\":\"14px\",\"bottom\":\"14px\",\"left\":\"28px\",\"right\":\"28px\"}}}} -->\n        <div class=\"wp-block-button\" style=\"font-size:16px;font-weight:600\"><a class=\"wp-block-button__link has-text-color has-background wp-element-button\" href=\"#request-proposal\" style=\"border-radius:6px;background-color:#ea580c;color:#ffffff;padding-top:14px;padding-right:28px;padding-bottom:14px;padding-left:28px\">Get Custom Line Layout &amp; Quote →</a></div>\n        <!-- /wp:button -->\n\n        <!-- wp:button {\"className\":\"is-style-outline\",\"style\":{\"border\":{\"radius\":\"6px\",\"width\":\"1px\"},\"color\":{\"text\":\"#f8fafc\"},\"typography\":{\"fontSize\":\"16px\",\"fontWeight\":\"600\"},\"spacing\":{\"padding\":{\"top\":\"14px\",\"bottom\":\"14px\",\"left\":\"24px\",\"right\":\"24px\"}}}} -->\n        <div class=\"wp-block-button is-style-outline\" style=\"font-size:16px;font-weight:600\"><a class=\"wp-block-button__link has-text-color wp-element-button\" href=\"/products/15-25m-industrial-line/\" style=\"border-radius:6px;border-width:1px;color:#f8fafc;padding-top:14px;padding-right:24px;padding-bottom:14px;padding-left:24px\">Explore 15–25m Line Architecture</a></div>\n        <!-- /wp:button -->\n      </div>\n      <!-- /wp:buttons -->\n    </div>\n    <!-- /wp:column -->\n\n    <!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"40%\"} -->\n    <div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:40%\">\n      <!-- wp:html -->\n      <!-- 高质感工程数字孪生监控卡片（完美替代暂缺视频，展现激光闭环实时公差） -->\n      <div style=\"background:rgba(30,41,59,0.85);border:1px solid #334155;border-radius:12px;padding:24px;font-family:\'JetBrains Mono\',monospace;box-shadow:0 20px 50px rgba(0,0,0,0.5);\">\n        <div style=\"display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #334155;padding-bottom:12px;margin-bottom:16px;\">\n          <span style=\"font-size:12px;color:#94a3b8;letter-spacing:0.05em;\">● CLOSED-LOOP PID TELEMETRY</span>\n          <span style=\"background:#065f46;color:#34d399;font-size:11px;padding:3px 8px;border-radius:4px;\">LOCKED ±0.02mm</span>\n        </div>\n        <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:16px;\">\n          <div style=\"background:#0f172a;padding:14px;border-radius:8px;border-left:3px solid #38bdf8;\">\n            <div style=\"font-size:11px;color:#64748b;\">LASER X-AXIS DIA.</div>\n            <div style=\"font-size:24px;font-weight:700;color:#f8fafc;\">1.750 <small style=\"font-size:12px;color:#38bdf8;\">mm</small></div>\n          </div>\n          <div style=\"background:#0f172a;padding:14px;border-radius:8px;border-left:3px solid #38bdf8;\">\n            <div style=\"font-size:11px;color:#64748b;\">LASER Y-AXIS DIA.</div>\n            <div style=\"font-size:24px;font-weight:700;color:#f8fafc;\">1.749 <small style=\"font-size:12px;color:#38bdf8;\">mm</small></div>\n          </div>\n          <div style=\"background:#0f172a;padding:14px;border-radius:8px;border-left:3px solid #22c55e;\">\n            <div style=\"font-size:11px;color:#64748b;\">OVALITY (X-Y)</div>\n            <div style=\"font-size:20px;font-weight:700;color:#22c55e;\">0.008 <small style=\"font-size:12px;\">mm</small></div>\n          </div>\n          <div style=\"background:#0f172a;padding:14px;border-radius:8px;border-left:3px solid #f59e0b;\">\n            <div style=\"font-size:11px;color:#64748b;\">MELT PRESSURE</div>\n            <div style=\"font-size:20px;font-weight:700;color:#f8fafc;\">14.2 <small style=\"font-size:12px;color:#94a3b8;\">±0.1 MPa</small></div>\n          </div>\n        </div>\n        <div style=\"font-size:12px;color:#cbd5e1;line-height:1.6;background:#0f172a;padding:12px;border-radius:6px;\">\n          <div>✔ <strong>Line Footprint:</strong> 15m–25m (Straight / L / U Layout)</div>\n          <div>✔ <strong>Screw &amp; Barrel:</strong> 100% In-House CNC Machined</div>\n          <div>✔ <strong>Turnkey Handover:</strong> Hardware + Plant CAD + Recipes</div>\n        </div>\n      </div>\n      <!-- /wp:html -->\n    </div>\n    <!-- /wp:column -->\n\n  </div>\n  <!-- /wp:columns -->\n\n  <!-- wp:html -->\n  <!-- 15-25米整线矢量工程蓝图 (Interactive SVG Engineering Schematic Fallback) -->\n  <div style=\"margin-top:48px;background:#1e293b;border:1px solid #334155;border-radius:10px;padding:20px;\">\n    <div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;flex-wrap:wrap;gap:8px;\">\n      <span style=\"font-size:12px;font-family:\'JetBrains Mono\',monospace;color:#38bdf8;font-weight:600;\">[SCHEMATIC BLUEPRINT] 15–25M CLOSED-LOOP INDUSTRIAL EXTRUSION ARCHITECTURE</span>\n      <span style=\"font-size:12px;color:#94a3b8;\">Total Effective Cooling Path: 8m–12m Multi-Stage Laminar Bath</span>\n    </div>\n    <svg viewBox=\"0 0 1100 170\" width=\"100%\" height=\"auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"15 to 25 meter 3D filament extrusion line technical schematic diagram\">\n      <rect width=\"1100\" height=\"170\" rx=\"6\" fill=\"#0f172a\"/>\n      <!-- 网格背景线 -->\n      <line x1=\"0\" y1=\"40\" x2=\"1100\" y2=\"40\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n      <line x1=\"0\" y1=\"85\" x2=\"1100\" y2=\"85\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n      <line x1=\"0\" y1=\"130\" x2=\"1100\" y2=\"130\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n      <!-- 耗材主线 (Filament Path) -->\n      <line x1=\"210\" y1=\"85\" x2=\"960\" y2=\"85\" stroke=\"#ea580c\" stroke-width=\"3\" stroke-dasharray=\"6,3\"/>\n      <!-- 1. 主挤出机 -->\n      <rect x=\"20\" y1=\"45\" y=\"45\" width=\"190\" height=\"75\" rx=\"4\" fill=\"#1e293b\" stroke=\"#38bdf8\" stroke-width=\"2\"/>\n      <text x=\"32\" y=\"70\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">01. CNC EXTRUDER</text>\n      <text x=\"32\" y=\"90\" fill=\"#f8fafc\" font-family=\"sans-serif\" font-size=\"11\">Barrier Screw 45/65mm</text>\n      <text x=\"32\" y=\"106\" fill=\"#94a3b8\" font-family=\"monospace\" font-size=\"10\">Dehumidifier &lt; 50ppm</text>\n      <!-- 2. 多段恒温冷却水槽 -->\n      <rect x=\"250\" y=\"50\" width=\"330\" height=\"65\" rx=\"4\" fill=\"#0c4a6e\" stroke=\"#0284c7\" stroke-width=\"2\"/>\n      <text x=\"265\" y=\"73\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">02. MULTI-STAGE LAMINAR BATH (8-12M)</text>\n      <text x=\"265\" y=\"92\" fill=\"#e0f2fe\" font-family=\"sans-serif\" font-size=\"11\">Zone A (55°C) → Zone B (40°C) → Zone C (25°C)</text>\n      <text x=\"265\" y=\"107\" fill=\"#7dd3fc\" font-family=\"monospace\" font-size=\"10\">Zero Ovality &amp; Zero Internal Voids</text>\n      <!-- 3. 双轴激光测径仪 -->\n      <rect x=\"615\" y=\"45\" width=\"130\" height=\"75\" rx=\"4\" fill=\"#1e293b\" stroke=\"#22c55e\" stroke-width=\"2\"/>\n      <text x=\"625\" y=\"70\" fill=\"#22c55e\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">03. LASER GAUGE</text>\n      <text x=\"625\" y=\"88\" fill=\"#f8fafc\" font-family=\"sans-serif\" font-size=\"11\">X/Y Dual-Axis</text>\n      <text x=\"625\" y=\"105\" fill=\"#4ade80\" font-family=\"monospace\" font-size=\"10\">±0.02mm Check</text>\n      <!-- 4. 伺服牵引机 -->\n      <rect x=\"780\" y=\"45\" width=\"130\" height=\"75\" rx=\"4\" fill=\"#1e293b\" stroke=\"#22c55e\" stroke-width=\"2\"/>\n      <text x=\"790\" y=\"70\" fill=\"#22c55e\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">04. SERVO PULLER</text>\n      <text x=\"790\" y=\"88\" fill=\"#f8fafc\" font-family=\"sans-serif\" font-size=\"11\">PID Sync Drive</text>\n      <text x=\"790\" y=\"105\" fill=\"#94a3b8\" font-family=\"monospace\" font-size=\"10\">&lt;10ms Response</text>\n      <!-- PID 闭环反馈连线 -->\n      <path d=\"M 680 120 L 680 150 L 845 150 L 845 120\" fill=\"none\" stroke=\"#22c55e\" stroke-width=\"2\" stroke-dasharray=\"4,4\"/>\n      <text x=\"705\" y=\"144\" fill=\"#4ade80\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">⇄ REAL-TIME PID CLOSED-LOOP</text>\n      <!-- 5. 双工位自动收卷机 -->\n      <rect x=\"945\" y=\"45\" width=\"135\" height=\"75\" rx=\"4\" fill=\"#1e293b\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n      <text x=\"955\" y=\"70\" fill=\"#f59e0b\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">05. DUAL SPOOLER</text>\n      <text x=\"955\" y=\"88\" fill=\"#f8fafc\" font-family=\"sans-serif\" font-size=\"11\">Servo Neat Wind</text>\n      <text x=\"955\" y=\"105\" fill=\"#fcd34d\" font-family=\"monospace\" font-size=\"10\">Auto Changeover</text>\n    </svg>\n  </div>\n  <!-- /wp:html -->\n\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"background\":\"#ffffff\",\"text\":\"#0f172a\"},\"spacing\":{\"padding\":{\"top\":\"80px\",\"bottom\":\"80px\",\"left\":\"24px\",\"right\":\"24px\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1280px\"}} -->\n<div class=\"wp-block-group alignfull has-text-color has-background\" style=\"background-color:#ffffff;color:#0f172a;padding-top:80px;padding-right:24px;padding-bottom:80px;padding-left:24px\">\n\n  <!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"13px\",\"fontWeight\":\"700\",\"letterSpacing\":\"0.08em\",\"textTransform\":\"uppercase\"},\"color\":{\"text\":\"#0284c7\"}}} -->\n  <p class=\"has-text-align-center has-text-color\" style=\"color:#0284c7;font-size:13px;font-weight:700;letter-spacing:0.08em;text-transform:uppercase\">APPLICATION-SPECIFIC EXTRUSION ARCHITECTURE</p>\n  <!-- /wp:paragraph -->\n\n  <!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"36px\",\"fontWeight\":\"800\"},\"spacing\":{\"margin\":{\"top\":\"8px\",\"bottom\":\"16px\"}}}} -->\n  <h2 class=\"wp-block-heading has-text-align-center\" style=\"margin-top:8px;margin-bottom:16px;font-size:36px;font-weight:800\">Choose Your Production Line by Polymer Chemistry</h2>\n  <!-- /wp:heading -->\n\n  <!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#475569\"},\"typography\":{\"fontSize\":\"17px\"},\"spacing\":{\"margin\":{\"bottom\":\"48px\"}}}} -->\n  <p class=\"has-text-align-center has-text-color\" style=\"color:#475569;margin-bottom:48px;font-size:17px\">Different polymers demand fundamentally different screw compression ratios, shear profiles, and cooling thermodynamics. We engineer material-dedicated production lines.</p>\n  <!-- /wp:paragraph -->\n\n  <!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"28px\",\"left\":\"28px\"}}}} -->\n  <div class=\"wp-block-columns\">\n\n    <!-- wp:column {\"style\":{\"border\":{\"width\":\"1px\",\"color\":\"#e2e8f0\",\"radius\":\"12px\"},\"spacing\":{\"padding\":{\"top\":\"32px\",\"bottom\":\"32px\",\"left\":\"28px\",\"right\":\"28px\"}},\"color\":{\"background\":\"#f8fafc\"}}} -->\n    <div class=\"wp-block-column has-border-color has-background\" style=\"border-color:#e2e8f0;border-width:1px;border-radius:12px;background-color:#f8fafc;padding-top:32px;padding-right:28px;padding-bottom:32px;padding-left:28px\">\n      <!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"12px\",\"fontWeight\":\"700\"},\"color\":{\"text\":\"#0284c7\"}}} -->\n      <p class=\"has-text-color\" style=\"color:#0284c7;font-size:12px;font-weight:700\">180°C – 260°C | HIGH-OUTPUT BIO-POLYMERS</p>\n      <!-- /wp:paragraph -->\n      <!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"22px\",\"fontWeight\":\"700\"}}} -->\n      <h3 class=\"wp-block-heading\" style=\"font-size:22px;font-weight:700\">PLA &amp; PETG High-Speed Extrusion Line</h3>\n      <!-- /wp:heading -->\n      <!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#475569\"},\"typography\":{\"fontSize\":\"15px\",\"lineHeight\":\"1.6\"}}} -->\n      <p class=\"has-text-color\" style=\"color:#475569;font-size:15px;line-height:1.6\">Optimized with a low-shear barrier screw to prevent molecular degradation and yellowing. Triple-stage gradient constant-temperature water bath eliminates brittle PETG filament syndrome.</p>\n      <!-- /wp:paragraph -->\n      <!-- wp:list {\"style\":{\"typography\":{\"fontSize\":\"14px\",\"lineHeight\":\"1.8\"}}} -->\n      <ul style=\"font-size:14px;line-height:1.8\">\n        <li><strong>Materials:</strong> PLA, PLA+, PETG, Wood/CF-PLA</li>\n        <li><strong>Output:</strong> 12 – 30 kg/h (45mm / 65mm Screw)</li>\n        <li><strong>Tolerance:</strong> 1.75mm / 2.85mm ±0.02mm</li>\n      </ul>\n      <!-- /wp:list -->\n      <!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"top\":\"20px\"}},\"typography\":{\"fontWeight\":\"700\"}}} -->\n      <p style=\"margin-top:20px;font-weight:700\"><a href=\"/products/pla-petg-filament-extrusion-line/\">Explore PLA/PETG Line Specs →</a></p>\n      <!-- /wp:paragraph -->\n    </div>\n    <!-- /wp:column -->\n\n    <!-- wp:column {\"style\":{\"border\":{\"width\":\"1px\",\"color\":\"#e2e8f0\",\"radius\":\"12px\"},\"spacing\":{\"padding\":{\"top\":\"32px\",\"bottom\":\"32px\",\"left\":\"28px\",\"right\":\"28px\"}},\"color\":{\"background\":\"#f8fafc\"}}} -->\n    <div class=\"wp-block-column has-border-color has-background\" style=\"border-color:#e2e8f0;border-width:1px;border-radius:12px;background-color:#f8fafc;padding-top:32px;padding-right:28px;padding-bottom:32px;padding-left:28px\">\n      <!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"12px\",\"fontWeight\":\"700\"},\"color\":{\"text\":\"#ea580c\"}}} -->\n      <p class=\"has-text-color\" style=\"color:#ea580c;font-size:12px;font-weight:700\">220°C – 350°C | SHRINKAGE &amp; VENTING CONTROL</p>\n      <!-- /wp:paragraph -->\n      <!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"22px\",\"fontWeight\":\"700\"}}} -->\n      <h3 class=\"wp-block-heading\" style=\"font-size:22px;font-weight:700\">ABS, HIPS &amp; Engineering Plastic Line</h3>\n      <!-- /wp:heading -->\n      <!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#475569\"},\"typography\":{\"fontSize\":\"15px\",\"lineHeight\":\"1.6\"}}} -->\n      <p class=\"has-text-color\" style=\"color:#475569;font-size:15px;line-height:1.6\">Engineered to conquer moisture sensitivity, styrene volatiles, and thermal shrinkage. Features precision degassing zones and thermally insulated annealing baths for zero micro-bubbles.</p>\n      <!-- /wp:paragraph -->\n      <!-- wp:list {\"style\":{\"typography\":{\"fontSize\":\"14px\",\"lineHeight\":\"1.8\"}}} -->\n      <ul style=\"font-size:14px;line-height:1.8\">\n        <li><strong>Materials:</strong> ABS, ASA, HIPS, PC, PA (Nylon), TPU</li>\n        <li><strong>Output:</strong> 10 – 25 kg/h Continuous Run</li>\n        <li><strong>Cooling:</strong> Insulated Multi-Zone Thermal Bath</li>\n      </ul>\n      <!-- /wp:list -->\n      <!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"top\":\"20px\"}},\"typography\":{\"fontWeight\":\"700\"}}} -->\n      <p style=\"margin-top:20px;font-weight:700\"><a href=\"/products/abs-hips-filament-extrusion-line/\">Explore ABS/HIPS Line Specs →</a></p>\n      <!-- /wp:paragraph -->\n    </div>\n    <!-- /wp:column -->\n\n    <!-- wp:column {\"style\":{\"border\":{\"width\":\"1px\",\"color\":\"#e2e8f0\",\"radius\":\"12px\"},\"spacing\":{\"padding\":{\"top\":\"32px\",\"bottom\":\"32px\",\"left\":\"28px\",\"right\":\"28px\"}},\"color\":{\"background\":\"#f8fafc\"}}} -->\n    <div class=\"wp-block-column has-border-color has-background\" style=\"border-color:#e2e8f0;border-width:1px;border-radius:12px;background-color:#f8fafc;padding-top:32px;padding-right:28px;padding-bottom:32px;padding-left:28px\">\n      <!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"12px\",\"fontWeight\":\"700\"},\"color\":{\"text\":\"#dc2626\"}}} -->\n      <p class=\"has-text-color\" style=\"color:#dc2626;font-size:12px;font-weight:700\">380°C – 500°C | AEROSPACE &amp; MEDICAL GRADE</p>\n      <!-- /wp:paragraph -->\n      <!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"22px\",\"fontWeight\":\"700\"}}} -->\n      <h3 class=\"wp-block-heading\" style=\"font-size:22px;font-weight:700\">PEEK &amp; Ultra-High-Temp Polymer Line</h3>\n      <!-- /wp:heading -->\n      <!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#475569\"},\"typography\":{\"fontSize\":\"15px\",\"lineHeight\":\"1.6\"}}} -->\n      <p class=\"has-text-color\" style=\"color:#475569;font-size:15px;line-height:1.6\">Built for extreme thermal stability up to 500°C. Utilizes wear-resistant bimetallic barrels, high-torque servo drives, and inline crystallization ovens with minimal raw resin waste.</p>\n      <!-- /wp:paragraph -->\n      <!-- wp:list {\"style\":{\"typography\":{\"fontSize\":\"14px\",\"lineHeight\":\"1.8\"}}} -->\n      <ul style=\"font-size:14px;line-height:1.8\">\n        <li><strong>Materials:</strong> PEEK, PEKK, PEI (Ultem), PPSU, CF-PEEK</li>\n        <li><strong>Barrel:</strong> Bimetallic HRC 65 + SSR PID ±0.5°C</li>\n        <li><strong>ROI Advantage:</strong> Low-Purge Volume Die Design</li>\n      </ul>\n      <!-- /wp:list -->\n      <!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"top\":\"20px\"}},\"typography\":{\"fontWeight\":\"700\"}}} -->\n      <p style=\"margin-top:20px;font-weight:700\"><a href=\"/products/peek-high-temp-filament-line/\">Explore PEEK High-Temp Specs →</a></p>\n      <!-- /wp:paragraph -->\n    </div>\n    <!-- /wp:column -->\n\n  </div>\n  <!-- /wp:columns -->\n\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"background\":\"#f1f5f9\",\"text\":\"#0f172a\"},\"spacing\":{\"padding\":{\"top\":\"80px\",\"bottom\":\"80px\",\"left\":\"24px\",\"right\":\"24px\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1280px\"}} -->\n<div id=\"request-proposal\" class=\"wp-block-group alignfull has-text-color has-background\" style=\"background-color:#f1f5f9;color:#0f172a;padding-top:80px;padding-right:24px;padding-bottom:80px;padding-left:24px\">\n  <!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"48px\",\"left\":\"48px\"}}}} -->\n  <div class=\"wp-block-columns\">\n    <!-- wp:column {\"width\":\"45%\"} -->\n    <div class=\"wp-block-column\" style=\"flex-basis:45%\">\n      <!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"13px\",\"fontWeight\":\"700\",\"letterSpacing\":\"0.08em\"},\"color\":{\"text\":\"#ea580c\"}}} -->\n      <p class=\"has-text-color\" style=\"color:#ea580c;font-size:13px;font-weight:700;letter-spacing:0.08em\">DIRECT FACTORY ENGINEERING CONSULTATION</p>\n      <!-- /wp:paragraph -->\n      <!-- wp:heading {\"style\":{\"typography\":{\"fontSize\":\"32px\",\"fontWeight\":\"800\"}}} -->\n      <h2 class=\"wp-block-heading\" style=\"font-size:32px;font-weight:800\">Request Your Custom Line Proposal &amp; CAD Floor Plan</h2>\n      <!-- /wp:heading -->\n      <!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#475569\"}}} -->\n      <p class=\"has-text-color\" style=\"color:#475569\">Select your target polymers and available workshop length. Our extrusion engineers and sales director will prepare a tailored configuration, output calculation, and itemized quotation within 24 hours.</p>\n      <!-- /wp:paragraph -->\n      <!-- wp:list {\"style\":{\"typography\":{\"lineHeight\":\"2\"}}} -->\n      <ul style=\"line-height:2\">\n        <li>✔ <strong>Itemized Hardware Quote</strong> (Extruder, Tank, Laser Gauge, Spooler)</li>\n        <li>✔ <strong>Custom 15–25m Workshop CAD Layout</strong> (Straight / L / U-Shape)</li>\n        <li>✔ <strong>Turnkey Process Recipe Handover Scope</strong></li>\n        <li>✔ <strong>Live Video Factory Acceptance Test (FAT) Scheduling</strong></li>\n      </ul>\n      <!-- /wp:list -->\n    </div>\n    <!-- /wp:column -->\n\n    <!-- wp:column {\"width\":\"55%\",\"style\":{\"color\":{\"background\":\"#ffffff\"},\"border\":{\"radius\":\"12px\",\"width\":\"1px\",\"color\":\"#cbd5e1\"},\"spacing\":{\"padding\":{\"top\":\"36px\",\"bottom\":\"36px\",\"left\":\"36px\",\"right\":\"36px\"}}}} -->\n    <div class=\"wp-block-column has-border-color has-background\" style=\"border-color:#cbd5e1;border-width:1px;border-radius:12px;background-color:#ffffff;padding-top:36px;padding-right:36px;padding-bottom:36px;padding-left:36px;flex-basis:55%\">\n      <!-- wp:shortcode -->\n      [fluentform id=\"1\"]\n      <!-- /wp:shortcode -->\n    </div>\n    <!-- /wp:column -->\n  </div>\n  <!-- /wp:columns -->\n</div>\n<!-- /wp:group -->', 'Home', '', 'inherit', 'closed', 'closed', '', '1784-autosave-v1', '', '', '2026-11-04 12:09:31', '2026-11-04 04:09:31', '', 1784, 'https://hermes-fs.test/?p=1856', 0, 'revision', '', 0);
INSERT INTO `wp_posts` VALUES (1857, 1, '2026-11-04 12:09:35', '2026-11-04 04:09:35', '<!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"background\":\"#0f172a\",\"text\":\"#f8fafc\"},\"spacing\":{\"padding\":{\"top\":\"90px\",\"bottom\":\"90px\",\"left\":\"24px\",\"right\":\"24px\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1280px\"}} -->\n<div class=\"wp-block-group alignfull has-text-color has-background\" style=\"background-color:#0f172a;color:#f8fafc;padding-top:90px;padding-right:24px;padding-bottom:90px;padding-left:24px\">\n\n  <!-- wp:columns {\"verticalAlignment\":\"center\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"48px\",\"left\":\"48px\"}}}} -->\n  <div class=\"wp-block-columns are-vertically-aligned-center\">\n\n    <!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"60%\"} -->\n    <div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:60%\">\n      <!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"13px\",\"fontWeight\":\"700\",\"letterSpacing\":\"0.08em\",\"textTransform\":\"uppercase\"},\"color\":{\"text\":\"#38bdf8\"}}} -->\n      <p class=\"has-text-color\" style=\"color:#38bdf8;font-size:13px;font-weight:700;letter-spacing:0.08em;text-transform:uppercase\">INDUSTRIAL 3D FILAMENT EXTRUSION SYSTEMS | 15–25M TURNKEY LINES</p>\n      <!-- /wp:paragraph -->\n\n      <!-- wp:heading {\"level\":1,\"style\":{\"typography\":{\"fontSize\":\"44px\",\"lineHeight\":\"1.18\",\"fontWeight\":\"800\"},\"spacing\":{\"margin\":{\"top\":\"12px\",\"bottom\":\"20px\"}}}} -->\n      <h1 class=\"wp-block-heading\" style=\"margin-top:12px;margin-bottom:20px;font-size:44px;font-weight:800;line-height:1.18\">Engineered for ±0.02mm Diameter Precision. Built for 24/7 Industrial Filament Production.</h1>\n      <!-- /wp:heading -->\n\n      <!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"18px\",\"lineHeight\":\"1.65\"},\"color\":{\"text\":\"#cbd5e1\"}}} -->\n      <p class=\"has-text-color\" style=\"color:#cbd5e1;font-size:18px;line-height:1.65\">Stop losing margin to ovality, diameter drift, and tangled spools. We manufacture heavy-duty 15–25m filament extrusion lines integrating <strong>in-house CNC-machined screws</strong>, <strong>real-time laser-to-puller closed-loop control</strong>, and <strong>validated polymer processing recipes</strong>—from standard PLA/PETG to ultra-high-temp PEEK.</p>\n      <!-- /wp:paragraph -->\n\n      <!-- wp:buttons {\"style\":{\"spacing\":{\"margin\":{\"top\":\"32px\"}}}} -->\n      <div class=\"wp-block-buttons\" style=\"margin-top:32px\">\n        <!-- wp:button {\"style\":{\"color\":{\"background\":\"#ea580c\",\"text\":\"#ffffff\"},\"border\":{\"radius\":\"6px\"},\"typography\":{\"fontSize\":\"16px\",\"fontWeight\":\"600\"},\"spacing\":{\"padding\":{\"top\":\"14px\",\"bottom\":\"14px\",\"left\":\"28px\",\"right\":\"28px\"}}}} -->\n        <div class=\"wp-block-button\" style=\"font-size:16px;font-weight:600\"><a class=\"wp-block-button__link has-text-color has-background wp-element-button\" href=\"#request-proposal\" style=\"border-radius:6px;background-color:#ea580c;color:#ffffff;padding-top:14px;padding-right:28px;padding-bottom:14px;padding-left:28px\">Get Custom Line Layout &amp; Quote →</a></div>\n        <!-- /wp:button -->\n\n        <!-- wp:button {\"className\":\"is-style-outline\",\"style\":{\"border\":{\"radius\":\"6px\",\"width\":\"1px\"},\"color\":{\"text\":\"#f8fafc\"},\"typography\":{\"fontSize\":\"16px\",\"fontWeight\":\"600\"},\"spacing\":{\"padding\":{\"top\":\"14px\",\"bottom\":\"14px\",\"left\":\"24px\",\"right\":\"24px\"}}}} -->\n        <div class=\"wp-block-button is-style-outline\" style=\"font-size:16px;font-weight:600\"><a class=\"wp-block-button__link has-text-color wp-element-button\" href=\"/products/15-25m-industrial-line/\" style=\"border-radius:6px;border-width:1px;color:#f8fafc;padding-top:14px;padding-right:24px;padding-bottom:14px;padding-left:24px\">Explore 15–25m Line Architecture</a></div>\n        <!-- /wp:button -->\n      </div>\n      <!-- /wp:buttons -->\n    </div>\n    <!-- /wp:column -->\n\n    <!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"40%\"} -->\n    <div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:40%\">\n      <!-- wp:html -->\n      <!-- 高质感工程数字孪生监控卡片（完美替代暂缺视频，展现激光闭环实时公差） -->\n      <div style=\"background:rgba(30,41,59,0.85);border:1px solid #334155;border-radius:12px;padding:24px;font-family:\'JetBrains Mono\',monospace;box-shadow:0 20px 50px rgba(0,0,0,0.5);\">\n        <div style=\"display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #334155;padding-bottom:12px;margin-bottom:16px;\">\n          <span style=\"font-size:12px;color:#94a3b8;letter-spacing:0.05em;\">● CLOSED-LOOP PID TELEMETRY</span>\n          <span style=\"background:#065f46;color:#34d399;font-size:11px;padding:3px 8px;border-radius:4px;\">LOCKED ±0.02mm</span>\n        </div>\n        <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:16px;\">\n          <div style=\"background:#0f172a;padding:14px;border-radius:8px;border-left:3px solid #38bdf8;\">\n            <div style=\"font-size:11px;color:#64748b;\">LASER X-AXIS DIA.</div>\n            <div style=\"font-size:24px;font-weight:700;color:#f8fafc;\">1.750 <small style=\"font-size:12px;color:#38bdf8;\">mm</small></div>\n          </div>\n          <div style=\"background:#0f172a;padding:14px;border-radius:8px;border-left:3px solid #38bdf8;\">\n            <div style=\"font-size:11px;color:#64748b;\">LASER Y-AXIS DIA.</div>\n            <div style=\"font-size:24px;font-weight:700;color:#f8fafc;\">1.749 <small style=\"font-size:12px;color:#38bdf8;\">mm</small></div>\n          </div>\n          <div style=\"background:#0f172a;padding:14px;border-radius:8px;border-left:3px solid #22c55e;\">\n            <div style=\"font-size:11px;color:#64748b;\">OVALITY (X-Y)</div>\n            <div style=\"font-size:20px;font-weight:700;color:#22c55e;\">0.008 <small style=\"font-size:12px;\">mm</small></div>\n          </div>\n          <div style=\"background:#0f172a;padding:14px;border-radius:8px;border-left:3px solid #f59e0b;\">\n            <div style=\"font-size:11px;color:#64748b;\">MELT PRESSURE</div>\n            <div style=\"font-size:20px;font-weight:700;color:#f8fafc;\">14.2 <small style=\"font-size:12px;color:#94a3b8;\">±0.1 MPa</small></div>\n          </div>\n        </div>\n        <div style=\"font-size:12px;color:#cbd5e1;line-height:1.6;background:#0f172a;padding:12px;border-radius:6px;\">\n          <div>✔ <strong>Line Footprint:</strong> 15m–25m (Straight / L / U Layout)</div>\n          <div>✔ <strong>Screw &amp; Barrel:</strong> 100% In-House CNC Machined</div>\n          <div>✔ <strong>Turnkey Handover:</strong> Hardware + Plant CAD + Recipes</div>\n        </div>\n      </div>\n      <!-- /wp:html -->\n    </div>\n    <!-- /wp:column -->\n\n  </div>\n  <!-- /wp:columns -->\n\n  <!-- wp:html -->\n  <!-- 15-25米整线矢量工程蓝图 (Interactive SVG Engineering Schematic Fallback) -->\n  <div style=\"margin-top:48px;background:#1e293b;border:1px solid #334155;border-radius:10px;padding:20px;\">\n    <div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;flex-wrap:wrap;gap:8px;\">\n      <span style=\"font-size:12px;font-family:\'JetBrains Mono\',monospace;color:#38bdf8;font-weight:600;\">[SCHEMATIC BLUEPRINT] 15–25M CLOSED-LOOP INDUSTRIAL EXTRUSION ARCHITECTURE</span>\n      <span style=\"font-size:12px;color:#94a3b8;\">Total Effective Cooling Path: 8m–12m Multi-Stage Laminar Bath</span>\n    </div>\n    <svg viewBox=\"0 0 1100 170\" width=\"100%\" height=\"auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"15 to 25 meter 3D filament extrusion line technical schematic diagram\">\n      <rect width=\"1100\" height=\"170\" rx=\"6\" fill=\"#0f172a\"/>\n      <!-- 网格背景线 -->\n      <line x1=\"0\" y1=\"40\" x2=\"1100\" y2=\"40\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n      <line x1=\"0\" y1=\"85\" x2=\"1100\" y2=\"85\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n      <line x1=\"0\" y1=\"130\" x2=\"1100\" y2=\"130\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n      <!-- 耗材主线 (Filament Path) -->\n      <line x1=\"210\" y1=\"85\" x2=\"960\" y2=\"85\" stroke=\"#ea580c\" stroke-width=\"3\" stroke-dasharray=\"6,3\"/>\n      <!-- 1. 主挤出机 -->\n      <rect x=\"20\" y1=\"45\" y=\"45\" width=\"190\" height=\"75\" rx=\"4\" fill=\"#1e293b\" stroke=\"#38bdf8\" stroke-width=\"2\"/>\n      <text x=\"32\" y=\"70\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">01. CNC EXTRUDER</text>\n      <text x=\"32\" y=\"90\" fill=\"#f8fafc\" font-family=\"sans-serif\" font-size=\"11\">Barrier Screw 45/65mm</text>\n      <text x=\"32\" y=\"106\" fill=\"#94a3b8\" font-family=\"monospace\" font-size=\"10\">Dehumidifier &lt; 50ppm</text>\n      <!-- 2. 多段恒温冷却水槽 -->\n      <rect x=\"250\" y=\"50\" width=\"330\" height=\"65\" rx=\"4\" fill=\"#0c4a6e\" stroke=\"#0284c7\" stroke-width=\"2\"/>\n      <text x=\"265\" y=\"73\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">02. MULTI-STAGE LAMINAR BATH (8-12M)</text>\n      <text x=\"265\" y=\"92\" fill=\"#e0f2fe\" font-family=\"sans-serif\" font-size=\"11\">Zone A (55°C) → Zone B (40°C) → Zone C (25°C)</text>\n      <text x=\"265\" y=\"107\" fill=\"#7dd3fc\" font-family=\"monospace\" font-size=\"10\">Zero Ovality &amp; Zero Internal Voids</text>\n      <!-- 3. 双轴激光测径仪 -->\n      <rect x=\"615\" y=\"45\" width=\"130\" height=\"75\" rx=\"4\" fill=\"#1e293b\" stroke=\"#22c55e\" stroke-width=\"2\"/>\n      <text x=\"625\" y=\"70\" fill=\"#22c55e\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">03. LASER GAUGE</text>\n      <text x=\"625\" y=\"88\" fill=\"#f8fafc\" font-family=\"sans-serif\" font-size=\"11\">X/Y Dual-Axis</text>\n      <text x=\"625\" y=\"105\" fill=\"#4ade80\" font-family=\"monospace\" font-size=\"10\">±0.02mm Check</text>\n      <!-- 4. 伺服牵引机 -->\n      <rect x=\"780\" y=\"45\" width=\"130\" height=\"75\" rx=\"4\" fill=\"#1e293b\" stroke=\"#22c55e\" stroke-width=\"2\"/>\n      <text x=\"790\" y=\"70\" fill=\"#22c55e\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">04. SERVO PULLER</text>\n      <text x=\"790\" y=\"88\" fill=\"#f8fafc\" font-family=\"sans-serif\" font-size=\"11\">PID Sync Drive</text>\n      <text x=\"790\" y=\"105\" fill=\"#94a3b8\" font-family=\"monospace\" font-size=\"10\">&lt;10ms Response</text>\n      <!-- PID 闭环反馈连线 -->\n      <path d=\"M 680 120 L 680 150 L 845 150 L 845 120\" fill=\"none\" stroke=\"#22c55e\" stroke-width=\"2\" stroke-dasharray=\"4,4\"/>\n      <text x=\"705\" y=\"144\" fill=\"#4ade80\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">⇄ REAL-TIME PID CLOSED-LOOP</text>\n      <!-- 5. 双工位自动收卷机 -->\n      <rect x=\"945\" y=\"45\" width=\"135\" height=\"75\" rx=\"4\" fill=\"#1e293b\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n      <text x=\"955\" y=\"70\" fill=\"#f59e0b\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">05. DUAL SPOOLER</text>\n      <text x=\"955\" y=\"88\" fill=\"#f8fafc\" font-family=\"sans-serif\" font-size=\"11\">Servo Neat Wind</text>\n      <text x=\"955\" y=\"105\" fill=\"#fcd34d\" font-family=\"monospace\" font-size=\"10\">Auto Changeover</text>\n    </svg>\n  </div>\n  <!-- /wp:html -->\n\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"background\":\"#ffffff\",\"text\":\"#0f172a\"},\"spacing\":{\"padding\":{\"top\":\"80px\",\"bottom\":\"80px\",\"left\":\"24px\",\"right\":\"24px\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1280px\"}} -->\n<div class=\"wp-block-group alignfull has-text-color has-background\" style=\"background-color:#ffffff;color:#0f172a;padding-top:80px;padding-right:24px;padding-bottom:80px;padding-left:24px\">\n\n  <!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"13px\",\"fontWeight\":\"700\",\"letterSpacing\":\"0.08em\",\"textTransform\":\"uppercase\"},\"color\":{\"text\":\"#0284c7\"}}} -->\n  <p class=\"has-text-align-center has-text-color\" style=\"color:#0284c7;font-size:13px;font-weight:700;letter-spacing:0.08em;text-transform:uppercase\">APPLICATION-SPECIFIC EXTRUSION ARCHITECTURE</p>\n  <!-- /wp:paragraph -->\n\n  <!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"36px\",\"fontWeight\":\"800\"},\"spacing\":{\"margin\":{\"top\":\"8px\",\"bottom\":\"16px\"}}}} -->\n  <h2 class=\"wp-block-heading has-text-align-center\" style=\"margin-top:8px;margin-bottom:16px;font-size:36px;font-weight:800\">Choose Your Production Line by Polymer Chemistry</h2>\n  <!-- /wp:heading -->\n\n  <!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#475569\"},\"typography\":{\"fontSize\":\"17px\"},\"spacing\":{\"margin\":{\"bottom\":\"48px\"}}}} -->\n  <p class=\"has-text-align-center has-text-color\" style=\"color:#475569;margin-bottom:48px;font-size:17px\">Different polymers demand fundamentally different screw compression ratios, shear profiles, and cooling thermodynamics. We engineer material-dedicated production lines.</p>\n  <!-- /wp:paragraph -->\n\n  <!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"28px\",\"left\":\"28px\"}}}} -->\n  <div class=\"wp-block-columns\">\n\n    <!-- wp:column {\"style\":{\"border\":{\"width\":\"1px\",\"color\":\"#e2e8f0\",\"radius\":\"12px\"},\"spacing\":{\"padding\":{\"top\":\"32px\",\"bottom\":\"32px\",\"left\":\"28px\",\"right\":\"28px\"}},\"color\":{\"background\":\"#f8fafc\"}}} -->\n    <div class=\"wp-block-column has-border-color has-background\" style=\"border-color:#e2e8f0;border-width:1px;border-radius:12px;background-color:#f8fafc;padding-top:32px;padding-right:28px;padding-bottom:32px;padding-left:28px\">\n      <!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"12px\",\"fontWeight\":\"700\"},\"color\":{\"text\":\"#0284c7\"}}} -->\n      <p class=\"has-text-color\" style=\"color:#0284c7;font-size:12px;font-weight:700\">180°C – 260°C | HIGH-OUTPUT BIO-POLYMERS</p>\n      <!-- /wp:paragraph -->\n      <!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"22px\",\"fontWeight\":\"700\"}}} -->\n      <h3 class=\"wp-block-heading\" style=\"font-size:22px;font-weight:700\">PLA &amp; PETG High-Speed Extrusion Line</h3>\n      <!-- /wp:heading -->\n      <!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#475569\"},\"typography\":{\"fontSize\":\"15px\",\"lineHeight\":\"1.6\"}}} -->\n      <p class=\"has-text-color\" style=\"color:#475569;font-size:15px;line-height:1.6\">Optimized with a low-shear barrier screw to prevent molecular degradation and yellowing. Triple-stage gradient constant-temperature water bath eliminates brittle PETG filament syndrome.</p>\n      <!-- /wp:paragraph -->\n      <!-- wp:list {\"style\":{\"typography\":{\"fontSize\":\"14px\",\"lineHeight\":\"1.8\"}}} -->\n      <ul style=\"font-size:14px;line-height:1.8\">\n        <li><strong>Materials:</strong> PLA, PLA+, PETG, Wood/CF-PLA</li>\n        <li><strong>Output:</strong> 12 – 30 kg/h (45mm / 65mm Screw)</li>\n        <li><strong>Tolerance:</strong> 1.75mm / 2.85mm ±0.02mm</li>\n      </ul>\n      <!-- /wp:list -->\n      <!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"top\":\"20px\"}},\"typography\":{\"fontWeight\":\"700\"}}} -->\n      <p style=\"margin-top:20px;font-weight:700\"><a href=\"/products/pla-petg-filament-extrusion-line/\">Explore PLA/PETG Line Specs →</a></p>\n      <!-- /wp:paragraph -->\n    </div>\n    <!-- /wp:column -->\n\n    <!-- wp:column {\"style\":{\"border\":{\"width\":\"1px\",\"color\":\"#e2e8f0\",\"radius\":\"12px\"},\"spacing\":{\"padding\":{\"top\":\"32px\",\"bottom\":\"32px\",\"left\":\"28px\",\"right\":\"28px\"}},\"color\":{\"background\":\"#f8fafc\"}}} -->\n    <div class=\"wp-block-column has-border-color has-background\" style=\"border-color:#e2e8f0;border-width:1px;border-radius:12px;background-color:#f8fafc;padding-top:32px;padding-right:28px;padding-bottom:32px;padding-left:28px\">\n      <!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"12px\",\"fontWeight\":\"700\"},\"color\":{\"text\":\"#ea580c\"}}} -->\n      <p class=\"has-text-color\" style=\"color:#ea580c;font-size:12px;font-weight:700\">220°C – 350°C | SHRINKAGE &amp; VENTING CONTROL</p>\n      <!-- /wp:paragraph -->\n      <!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"22px\",\"fontWeight\":\"700\"}}} -->\n      <h3 class=\"wp-block-heading\" style=\"font-size:22px;font-weight:700\">ABS, HIPS &amp; Engineering Plastic Line</h3>\n      <!-- /wp:heading -->\n      <!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#475569\"},\"typography\":{\"fontSize\":\"15px\",\"lineHeight\":\"1.6\"}}} -->\n      <p class=\"has-text-color\" style=\"color:#475569;font-size:15px;line-height:1.6\">Engineered to conquer moisture sensitivity, styrene volatiles, and thermal shrinkage. Features precision degassing zones and thermally insulated annealing baths for zero micro-bubbles.</p>\n      <!-- /wp:paragraph -->\n      <!-- wp:list {\"style\":{\"typography\":{\"fontSize\":\"14px\",\"lineHeight\":\"1.8\"}}} -->\n      <ul style=\"font-size:14px;line-height:1.8\">\n        <li><strong>Materials:</strong> ABS, ASA, HIPS, PC, PA (Nylon), TPU</li>\n        <li><strong>Output:</strong> 10 – 25 kg/h Continuous Run</li>\n        <li><strong>Cooling:</strong> Insulated Multi-Zone Thermal Bath</li>\n      </ul>\n      <!-- /wp:list -->\n      <!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"top\":\"20px\"}},\"typography\":{\"fontWeight\":\"700\"}}} -->\n      <p style=\"margin-top:20px;font-weight:700\"><a href=\"/products/abs-hips-filament-extrusion-line/\">Explore ABS/HIPS Line Specs →</a></p>\n      <!-- /wp:paragraph -->\n    </div>\n    <!-- /wp:column -->\n\n    <!-- wp:column {\"style\":{\"border\":{\"width\":\"1px\",\"color\":\"#e2e8f0\",\"radius\":\"12px\"},\"spacing\":{\"padding\":{\"top\":\"32px\",\"bottom\":\"32px\",\"left\":\"28px\",\"right\":\"28px\"}},\"color\":{\"background\":\"#f8fafc\"}}} -->\n    <div class=\"wp-block-column has-border-color has-background\" style=\"border-color:#e2e8f0;border-width:1px;border-radius:12px;background-color:#f8fafc;padding-top:32px;padding-right:28px;padding-bottom:32px;padding-left:28px\">\n      <!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"12px\",\"fontWeight\":\"700\"},\"color\":{\"text\":\"#dc2626\"}}} -->\n      <p class=\"has-text-color\" style=\"color:#dc2626;font-size:12px;font-weight:700\">380°C – 500°C | AEROSPACE &amp; MEDICAL GRADE</p>\n      <!-- /wp:paragraph -->\n      <!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"22px\",\"fontWeight\":\"700\"}}} -->\n      <h3 class=\"wp-block-heading\" style=\"font-size:22px;font-weight:700\">PEEK &amp; Ultra-High-Temp Polymer Line</h3>\n      <!-- /wp:heading -->\n      <!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#475569\"},\"typography\":{\"fontSize\":\"15px\",\"lineHeight\":\"1.6\"}}} -->\n      <p class=\"has-text-color\" style=\"color:#475569;font-size:15px;line-height:1.6\">Built for extreme thermal stability up to 500°C. Utilizes wear-resistant bimetallic barrels, high-torque servo drives, and inline crystallization ovens with minimal raw resin waste.</p>\n      <!-- /wp:paragraph -->\n      <!-- wp:list {\"style\":{\"typography\":{\"fontSize\":\"14px\",\"lineHeight\":\"1.8\"}}} -->\n      <ul style=\"font-size:14px;line-height:1.8\">\n        <li><strong>Materials:</strong> PEEK, PEKK, PEI (Ultem), PPSU, CF-PEEK</li>\n        <li><strong>Barrel:</strong> Bimetallic HRC 65 + SSR PID ±0.5°C</li>\n        <li><strong>ROI Advantage:</strong> Low-Purge Volume Die Design</li>\n      </ul>\n      <!-- /wp:list -->\n      <!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"top\":\"20px\"}},\"typography\":{\"fontWeight\":\"700\"}}} -->\n      <p style=\"margin-top:20px;font-weight:700\"><a href=\"/products/peek-high-temp-filament-line/\">Explore PEEK High-Temp Specs →</a></p>\n      <!-- /wp:paragraph -->\n    </div>\n    <!-- /wp:column -->\n\n  </div>\n  <!-- /wp:columns -->\n\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"background\":\"#f1f5f9\",\"text\":\"#0f172a\"},\"spacing\":{\"padding\":{\"top\":\"80px\",\"bottom\":\"80px\",\"left\":\"24px\",\"right\":\"24px\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1280px\"}} -->\n<div id=\"request-proposal\" class=\"wp-block-group alignfull has-text-color has-background\" style=\"background-color:#f1f5f9;color:#0f172a;padding-top:80px;padding-right:24px;padding-bottom:80px;padding-left:24px\">\n  <!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"48px\",\"left\":\"48px\"}}}} -->\n  <div class=\"wp-block-columns\">\n    <!-- wp:column {\"width\":\"45%\"} -->\n    <div class=\"wp-block-column\" style=\"flex-basis:45%\">\n      <!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"13px\",\"fontWeight\":\"700\",\"letterSpacing\":\"0.08em\"},\"color\":{\"text\":\"#ea580c\"}}} -->\n      <p class=\"has-text-color\" style=\"color:#ea580c;font-size:13px;font-weight:700;letter-spacing:0.08em\">DIRECT FACTORY ENGINEERING CONSULTATION</p>\n      <!-- /wp:paragraph -->\n      <!-- wp:heading {\"style\":{\"typography\":{\"fontSize\":\"32px\",\"fontWeight\":\"800\"}}} -->\n      <h2 class=\"wp-block-heading\" style=\"font-size:32px;font-weight:800\">Request Your Custom Line Proposal &amp; CAD Floor Plan</h2>\n      <!-- /wp:heading -->\n      <!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#475569\"}}} -->\n      <p class=\"has-text-color\" style=\"color:#475569\">Select your target polymers and available workshop length. Our extrusion engineers and sales director will prepare a tailored configuration, output calculation, and itemized quotation within 24 hours.</p>\n      <!-- /wp:paragraph -->\n      <!-- wp:list {\"style\":{\"typography\":{\"lineHeight\":\"2\"}}} -->\n      <ul style=\"line-height:2\">\n        <li>✔ <strong>Itemized Hardware Quote</strong> (Extruder, Tank, Laser Gauge, Spooler)</li>\n        <li>✔ <strong>Custom 15–25m Workshop CAD Layout</strong> (Straight / L / U-Shape)</li>\n        <li>✔ <strong>Turnkey Process Recipe Handover Scope</strong></li>\n        <li>✔ <strong>Live Video Factory Acceptance Test (FAT) Scheduling</strong></li>\n      </ul>\n      <!-- /wp:list -->\n    </div>\n    <!-- /wp:column -->\n\n    <!-- wp:column {\"width\":\"55%\",\"style\":{\"color\":{\"background\":\"#ffffff\"},\"border\":{\"radius\":\"12px\",\"width\":\"1px\",\"color\":\"#cbd5e1\"},\"spacing\":{\"padding\":{\"top\":\"36px\",\"bottom\":\"36px\",\"left\":\"36px\",\"right\":\"36px\"}}}} -->\n    <div class=\"wp-block-column has-border-color has-background\" style=\"border-color:#cbd5e1;border-width:1px;border-radius:12px;background-color:#ffffff;padding-top:36px;padding-right:36px;padding-bottom:36px;padding-left:36px;flex-basis:55%\">\n      <!-- wp:shortcode -->\n      [fluentform id=\"1\"]\n      <!-- /wp:shortcode -->\n    </div>\n    <!-- /wp:column -->\n  </div>\n  <!-- /wp:columns -->\n</div>\n<!-- /wp:group -->', 'Home', '', 'inherit', 'closed', 'closed', '', '1784-revision-v1', '', '', '2026-11-04 12:09:35', '2026-11-04 04:09:35', '', 1784, 'https://hermes-fs.test/?p=1857', 0, 'revision', '', 0);
INSERT INTO `wp_posts` VALUES (1858, 1, '2026-11-04 12:14:43', '2026-11-04 04:14:43', '<!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"background\":\"#0f172a\",\"text\":\"#f8fafc\"},\"spacing\":{\"padding\":{\"top\":\"0px\",\"bottom\":\"90px\",\"left\":\"24px\",\"right\":\"24px\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1280px\"}} -->\n<div class=\"wp-block-group alignfull has-text-color has-background\" style=\"color:#f8fafc;background-color:#0f172a;padding-top:0px;padding-right:24px;padding-bottom:90px;padding-left:24px\"><!-- wp:columns {\"verticalAlignment\":\"center\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"48px\",\"left\":\"48px\"}}}} -->\n<div class=\"wp-block-columns are-vertically-aligned-center\"><!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"60%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:60%\"><!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"13px\",\"fontWeight\":\"700\",\"letterSpacing\":\"0.08em\",\"textTransform\":\"uppercase\"},\"color\":{\"text\":\"#38bdf8\"}}} -->\n<p class=\"has-text-color\" style=\"color:#38bdf8;font-size:13px;font-weight:700;letter-spacing:0.08em;text-transform:uppercase\">INDUSTRIAL 3D FILAMENT EXTRUSION SYSTEMS | 15–25M TURNKEY LINES</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":1,\"style\":{\"typography\":{\"fontSize\":\"44px\",\"lineHeight\":\"1.18\",\"fontWeight\":\"800\"},\"spacing\":{\"margin\":{\"top\":\"12px\",\"bottom\":\"20px\"}}}} -->\n<h1 class=\"wp-block-heading\" style=\"margin-top:12px;margin-bottom:20px;font-size:44px;font-weight:800;line-height:1.18\">Engineered for ±0.02mm Diameter Precision. Built for 24/7 Industrial Filament Production.</h1>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"18px\",\"lineHeight\":\"1.65\"},\"color\":{\"text\":\"#cbd5e1\"}}} -->\n<p class=\"has-text-color\" style=\"color:#cbd5e1;font-size:18px;line-height:1.65\">Stop losing margin to ovality, diameter drift, and tangled spools. We manufacture heavy-duty 15–25m filament extrusion lines integrating <strong>in-house CNC-machined screws</strong>, <strong>real-time laser-to-puller closed-loop control</strong>, and <strong>validated polymer processing recipes</strong>—from standard PLA/PETG to ultra-high-temp PEEK.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"style\":{\"spacing\":{\"margin\":{\"top\":\"32px\"}}}} -->\n<div class=\"wp-block-buttons\" style=\"margin-top:32px\"><!-- wp:button {\"style\":{\"color\":{\"background\":\"#ea580c\",\"text\":\"#ffffff\"},\"border\":{\"radius\":\"6px\"},\"typography\":{\"fontSize\":\"16px\",\"fontWeight\":\"600\"},\"spacing\":{\"padding\":{\"top\":\"14px\",\"bottom\":\"14px\",\"left\":\"28px\",\"right\":\"28px\"}}}} -->\n<div class=\"wp-block-button\" style=\"font-size:16px;font-weight:600\"><a class=\"wp-block-button__link has-text-color has-background wp-element-button\" href=\"#request-proposal\" style=\"border-radius:6px;background-color:#ea580c;color:#ffffff;padding-top:14px;padding-right:28px;padding-bottom:14px;padding-left:28px\">Get Custom Line Layout &amp; Quote →</a></div>\n<!-- /wp:button -->\n\n<!-- wp:button {\"className\":\"is-style-outline\",\"style\":{\"border\":{\"radius\":\"6px\",\"width\":\"1px\"},\"color\":{\"text\":\"#f8fafc\"},\"typography\":{\"fontSize\":\"16px\",\"fontWeight\":\"600\"},\"spacing\":{\"padding\":{\"top\":\"14px\",\"bottom\":\"14px\",\"left\":\"24px\",\"right\":\"24px\"}}}} -->\n<div class=\"wp-block-button is-style-outline\" style=\"font-size:16px;font-weight:600\"><a class=\"wp-block-button__link has-text-color wp-element-button\" href=\"/products/15-25m-industrial-line/\" style=\"border-radius:6px;border-width:1px;color:#f8fafc;padding-top:14px;padding-right:24px;padding-bottom:14px;padding-left:24px\">Explore 15–25m Line Architecture</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"40%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:40%\"><!-- wp:html -->\n<!-- 高质感工程数字孪生监控卡片（完美替代暂缺视频，展现激光闭环实时公差） -->\n      <div style=\"background:rgba(30,41,59,0.85);border:1px solid #334155;border-radius:12px;padding:24px;font-family:\'JetBrains Mono\',monospace;box-shadow:0 20px 50px rgba(0,0,0,0.5);\">\n        <div style=\"display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #334155;padding-bottom:12px;margin-bottom:16px;\">\n          <span style=\"font-size:12px;color:#94a3b8;letter-spacing:0.05em;\">● CLOSED-LOOP PID TELEMETRY</span>\n          <span style=\"background:#065f46;color:#34d399;font-size:11px;padding:3px 8px;border-radius:4px;\">LOCKED ±0.02mm</span>\n        </div>\n        <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:16px;\">\n          <div style=\"background:#0f172a;padding:14px;border-radius:8px;border-left:3px solid #38bdf8;\">\n            <div style=\"font-size:11px;color:#64748b;\">LASER X-AXIS DIA.</div>\n            <div style=\"font-size:24px;font-weight:700;color:#f8fafc;\">1.750 <small style=\"font-size:12px;color:#38bdf8;\">mm</small></div>\n          </div>\n          <div style=\"background:#0f172a;padding:14px;border-radius:8px;border-left:3px solid #38bdf8;\">\n            <div style=\"font-size:11px;color:#64748b;\">LASER Y-AXIS DIA.</div>\n            <div style=\"font-size:24px;font-weight:700;color:#f8fafc;\">1.749 <small style=\"font-size:12px;color:#38bdf8;\">mm</small></div>\n          </div>\n          <div style=\"background:#0f172a;padding:14px;border-radius:8px;border-left:3px solid #22c55e;\">\n            <div style=\"font-size:11px;color:#64748b;\">OVALITY (X-Y)</div>\n            <div style=\"font-size:20px;font-weight:700;color:#22c55e;\">0.008 <small style=\"font-size:12px;\">mm</small></div>\n          </div>\n          <div style=\"background:#0f172a;padding:14px;border-radius:8px;border-left:3px solid #f59e0b;\">\n            <div style=\"font-size:11px;color:#64748b;\">MELT PRESSURE</div>\n            <div style=\"font-size:20px;font-weight:700;color:#f8fafc;\">14.2 <small style=\"font-size:12px;color:#94a3b8;\">±0.1 MPa</small></div>\n          </div>\n        </div>\n        <div style=\"font-size:12px;color:#cbd5e1;line-height:1.6;background:#0f172a;padding:12px;border-radius:6px;\">\n          <div>✔ <strong>Line Footprint:</strong> 15m–25m (Straight / L / U Layout)</div>\n          <div>✔ <strong>Screw &amp; Barrel:</strong> 100% In-House CNC Machined</div>\n          <div>✔ <strong>Turnkey Handover:</strong> Hardware + Plant CAD + Recipes</div>\n        </div>\n      </div>\n<!-- /wp:html --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:html -->\n<!-- 15-25米整线矢量工程蓝图 (Interactive SVG Engineering Schematic Fallback) -->\n  <div style=\"margin-top:48px;background:#1e293b;border:1px solid #334155;border-radius:10px;padding:20px;\">\n    <div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;flex-wrap:wrap;gap:8px;\">\n      <span style=\"font-size:12px;font-family:\'JetBrains Mono\',monospace;color:#38bdf8;font-weight:600;\">[SCHEMATIC BLUEPRINT] 15–25M CLOSED-LOOP INDUSTRIAL EXTRUSION ARCHITECTURE</span>\n      <span style=\"font-size:12px;color:#94a3b8;\">Total Effective Cooling Path: 8m–12m Multi-Stage Laminar Bath</span>\n    </div>\n    <svg viewBox=\"0 0 1100 170\" width=\"100%\" height=\"auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"15 to 25 meter 3D filament extrusion line technical schematic diagram\">\n      <rect width=\"1100\" height=\"170\" rx=\"6\" fill=\"#0f172a\"/>\n      <!-- 网格背景线 -->\n      <line x1=\"0\" y1=\"40\" x2=\"1100\" y2=\"40\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n      <line x1=\"0\" y1=\"85\" x2=\"1100\" y2=\"85\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n      <line x1=\"0\" y1=\"130\" x2=\"1100\" y2=\"130\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n      <!-- 耗材主线 (Filament Path) -->\n      <line x1=\"210\" y1=\"85\" x2=\"960\" y2=\"85\" stroke=\"#ea580c\" stroke-width=\"3\" stroke-dasharray=\"6,3\"/>\n      <!-- 1. 主挤出机 -->\n      <rect x=\"20\" y1=\"45\" y=\"45\" width=\"190\" height=\"75\" rx=\"4\" fill=\"#1e293b\" stroke=\"#38bdf8\" stroke-width=\"2\"/>\n      <text x=\"32\" y=\"70\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">01. CNC EXTRUDER</text>\n      <text x=\"32\" y=\"90\" fill=\"#f8fafc\" font-family=\"sans-serif\" font-size=\"11\">Barrier Screw 45/65mm</text>\n      <text x=\"32\" y=\"106\" fill=\"#94a3b8\" font-family=\"monospace\" font-size=\"10\">Dehumidifier &lt; 50ppm</text>\n      <!-- 2. 多段恒温冷却水槽 -->\n      <rect x=\"250\" y=\"50\" width=\"330\" height=\"65\" rx=\"4\" fill=\"#0c4a6e\" stroke=\"#0284c7\" stroke-width=\"2\"/>\n      <text x=\"265\" y=\"73\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">02. MULTI-STAGE LAMINAR BATH (8-12M)</text>\n      <text x=\"265\" y=\"92\" fill=\"#e0f2fe\" font-family=\"sans-serif\" font-size=\"11\">Zone A (55°C) → Zone B (40°C) → Zone C (25°C)</text>\n      <text x=\"265\" y=\"107\" fill=\"#7dd3fc\" font-family=\"monospace\" font-size=\"10\">Zero Ovality &amp; Zero Internal Voids</text>\n      <!-- 3. 双轴激光测径仪 -->\n      <rect x=\"615\" y=\"45\" width=\"130\" height=\"75\" rx=\"4\" fill=\"#1e293b\" stroke=\"#22c55e\" stroke-width=\"2\"/>\n      <text x=\"625\" y=\"70\" fill=\"#22c55e\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">03. LASER GAUGE</text>\n      <text x=\"625\" y=\"88\" fill=\"#f8fafc\" font-family=\"sans-serif\" font-size=\"11\">X/Y Dual-Axis</text>\n      <text x=\"625\" y=\"105\" fill=\"#4ade80\" font-family=\"monospace\" font-size=\"10\">±0.02mm Check</text>\n      <!-- 4. 伺服牵引机 -->\n      <rect x=\"780\" y=\"45\" width=\"130\" height=\"75\" rx=\"4\" fill=\"#1e293b\" stroke=\"#22c55e\" stroke-width=\"2\"/>\n      <text x=\"790\" y=\"70\" fill=\"#22c55e\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">04. SERVO PULLER</text>\n      <text x=\"790\" y=\"88\" fill=\"#f8fafc\" font-family=\"sans-serif\" font-size=\"11\">PID Sync Drive</text>\n      <text x=\"790\" y=\"105\" fill=\"#94a3b8\" font-family=\"monospace\" font-size=\"10\">&lt;10ms Response</text>\n      <!-- PID 闭环反馈连线 -->\n      <path d=\"M 680 120 L 680 150 L 845 150 L 845 120\" fill=\"none\" stroke=\"#22c55e\" stroke-width=\"2\" stroke-dasharray=\"4,4\"/>\n      <text x=\"705\" y=\"144\" fill=\"#4ade80\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">⇄ REAL-TIME PID CLOSED-LOOP</text>\n      <!-- 5. 双工位自动收卷机 -->\n      <rect x=\"945\" y=\"45\" width=\"135\" height=\"75\" rx=\"4\" fill=\"#1e293b\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n      <text x=\"955\" y=\"70\" fill=\"#f59e0b\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">05. DUAL SPOOLER</text>\n      <text x=\"955\" y=\"88\" fill=\"#f8fafc\" font-family=\"sans-serif\" font-size=\"11\">Servo Neat Wind</text>\n      <text x=\"955\" y=\"105\" fill=\"#fcd34d\" font-family=\"monospace\" font-size=\"10\">Auto Changeover</text>\n    </svg>\n  </div>\n<!-- /wp:html --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"background\":\"#ffffff\",\"text\":\"#0f172a\"},\"spacing\":{\"padding\":{\"top\":\"80px\",\"bottom\":\"80px\",\"left\":\"24px\",\"right\":\"24px\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1280px\"}} -->\n<div class=\"wp-block-group alignfull has-text-color has-background\" style=\"color:#0f172a;background-color:#ffffff;padding-top:80px;padding-right:24px;padding-bottom:80px;padding-left:24px\"><!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"13px\",\"fontWeight\":\"700\",\"letterSpacing\":\"0.08em\",\"textTransform\":\"uppercase\",\"textAlign\":\"center\"},\"color\":{\"text\":\"#0284c7\"}}} -->\n<p class=\"has-text-align-center has-text-color\" style=\"color:#0284c7;font-size:13px;font-weight:700;letter-spacing:0.08em;text-transform:uppercase\">APPLICATION-SPECIFIC EXTRUSION ARCHITECTURE</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"fontSize\":\"36px\",\"fontWeight\":\"800\",\"textAlign\":\"center\"},\"spacing\":{\"margin\":{\"top\":\"8px\",\"bottom\":\"16px\"}}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\" style=\"margin-top:8px;margin-bottom:16px;font-size:36px;font-weight:800\">Choose Your Production Line by Polymer Chemistry</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#475569\"},\"typography\":{\"fontSize\":\"17px\",\"textAlign\":\"center\"},\"spacing\":{\"margin\":{\"bottom\":\"48px\"}}}} -->\n<p class=\"has-text-align-center has-text-color\" style=\"color:#475569;margin-bottom:48px;font-size:17px\">Different polymers demand fundamentally different screw compression ratios, shear profiles, and cooling thermodynamics. We engineer material-dedicated production lines.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"28px\",\"left\":\"28px\"}}}} -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"style\":{\"border\":{\"width\":\"1px\",\"color\":\"#e2e8f0\",\"radius\":\"12px\"},\"spacing\":{\"padding\":{\"top\":\"32px\",\"bottom\":\"32px\",\"left\":\"28px\",\"right\":\"28px\"}},\"color\":{\"background\":\"#f8fafc\"}}} -->\n<div class=\"wp-block-column has-border-color has-background\" style=\"border-color:#e2e8f0;border-width:1px;border-radius:12px;background-color:#f8fafc;padding-top:32px;padding-right:28px;padding-bottom:32px;padding-left:28px\"><!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"12px\",\"fontWeight\":\"700\"},\"color\":{\"text\":\"#0284c7\"}}} -->\n<p class=\"has-text-color\" style=\"color:#0284c7;font-size:12px;font-weight:700\">180°C – 260°C | HIGH-OUTPUT BIO-POLYMERS</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"22px\",\"fontWeight\":\"700\"}}} -->\n<h3 class=\"wp-block-heading\" style=\"font-size:22px;font-weight:700\">PLA &amp; PETG High-Speed Extrusion Line</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#475569\"},\"typography\":{\"fontSize\":\"15px\",\"lineHeight\":\"1.6\"}}} -->\n<p class=\"has-text-color\" style=\"color:#475569;font-size:15px;line-height:1.6\">Optimized with a low-shear barrier screw to prevent molecular degradation and yellowing. Triple-stage gradient constant-temperature water bath eliminates brittle PETG filament syndrome.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"style\":{\"typography\":{\"fontSize\":\"14px\",\"lineHeight\":\"1.8\"}}} -->\n<ul style=\"font-size:14px;line-height:1.8\" class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>Materials:</strong> PLA, PLA+, PETG, Wood/CF-PLA</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Output:</strong> 12 – 30 kg/h (45mm / 65mm Screw)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Tolerance:</strong> 1.75mm / 2.85mm ±0.02mm</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"top\":\"20px\"}},\"typography\":{\"fontWeight\":\"700\"}}} -->\n<p style=\"margin-top:20px;font-weight:700\"><a href=\"/products/pla-petg-filament-extrusion-line/\">Explore PLA/PETG Line Specs →</a></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"border\":{\"width\":\"1px\",\"color\":\"#e2e8f0\",\"radius\":\"12px\"},\"spacing\":{\"padding\":{\"top\":\"32px\",\"bottom\":\"32px\",\"left\":\"28px\",\"right\":\"28px\"}},\"color\":{\"background\":\"#f8fafc\"}}} -->\n<div class=\"wp-block-column has-border-color has-background\" style=\"border-color:#e2e8f0;border-width:1px;border-radius:12px;background-color:#f8fafc;padding-top:32px;padding-right:28px;padding-bottom:32px;padding-left:28px\"><!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"12px\",\"fontWeight\":\"700\"},\"color\":{\"text\":\"#ea580c\"}}} -->\n<p class=\"has-text-color\" style=\"color:#ea580c;font-size:12px;font-weight:700\">220°C – 350°C | SHRINKAGE &amp; VENTING CONTROL</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"22px\",\"fontWeight\":\"700\"}}} -->\n<h3 class=\"wp-block-heading\" style=\"font-size:22px;font-weight:700\">ABS, HIPS &amp; Engineering Plastic Line</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#475569\"},\"typography\":{\"fontSize\":\"15px\",\"lineHeight\":\"1.6\"}}} -->\n<p class=\"has-text-color\" style=\"color:#475569;font-size:15px;line-height:1.6\">Engineered to conquer moisture sensitivity, styrene volatiles, and thermal shrinkage. Features precision degassing zones and thermally insulated annealing baths for zero micro-bubbles.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"style\":{\"typography\":{\"fontSize\":\"14px\",\"lineHeight\":\"1.8\"}}} -->\n<ul style=\"font-size:14px;line-height:1.8\" class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>Materials:</strong> ABS, ASA, HIPS, PC, PA (Nylon), TPU</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Output:</strong> 10 – 25 kg/h Continuous Run</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Cooling:</strong> Insulated Multi-Zone Thermal Bath</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"top\":\"20px\"}},\"typography\":{\"fontWeight\":\"700\"}}} -->\n<p style=\"margin-top:20px;font-weight:700\"><a href=\"/products/abs-hips-filament-extrusion-line/\">Explore ABS/HIPS Line Specs →</a></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"border\":{\"width\":\"1px\",\"color\":\"#e2e8f0\",\"radius\":\"12px\"},\"spacing\":{\"padding\":{\"top\":\"32px\",\"bottom\":\"32px\",\"left\":\"28px\",\"right\":\"28px\"}},\"color\":{\"background\":\"#f8fafc\"}}} -->\n<div class=\"wp-block-column has-border-color has-background\" style=\"border-color:#e2e8f0;border-width:1px;border-radius:12px;background-color:#f8fafc;padding-top:32px;padding-right:28px;padding-bottom:32px;padding-left:28px\"><!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"12px\",\"fontWeight\":\"700\"},\"color\":{\"text\":\"#dc2626\"}}} -->\n<p class=\"has-text-color\" style=\"color:#dc2626;font-size:12px;font-weight:700\">380°C – 500°C | AEROSPACE &amp; MEDICAL GRADE</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"22px\",\"fontWeight\":\"700\"}}} -->\n<h3 class=\"wp-block-heading\" style=\"font-size:22px;font-weight:700\">PEEK &amp; Ultra-High-Temp Polymer Line</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#475569\"},\"typography\":{\"fontSize\":\"15px\",\"lineHeight\":\"1.6\"}}} -->\n<p class=\"has-text-color\" style=\"color:#475569;font-size:15px;line-height:1.6\">Built for extreme thermal stability up to 500°C. Utilizes wear-resistant bimetallic barrels, high-torque servo drives, and inline crystallization ovens with minimal raw resin waste.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"style\":{\"typography\":{\"fontSize\":\"14px\",\"lineHeight\":\"1.8\"}}} -->\n<ul style=\"font-size:14px;line-height:1.8\" class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>Materials:</strong> PEEK, PEKK, PEI (Ultem), PPSU, CF-PEEK</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Barrel:</strong> Bimetallic HRC 65 + SSR PID ±0.5°C</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>ROI Advantage:</strong> Low-Purge Volume Die Design</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"top\":\"20px\"}},\"typography\":{\"fontWeight\":\"700\"}}} -->\n<p style=\"margin-top:20px;font-weight:700\"><a href=\"/products/peek-high-temp-filament-line/\">Explore PEEK High-Temp Specs →</a></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"background\":\"#f1f5f9\",\"text\":\"#0f172a\"},\"spacing\":{\"padding\":{\"top\":\"80px\",\"bottom\":\"80px\",\"left\":\"24px\",\"right\":\"24px\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1280px\"},\"anchor\":\"request-proposal\"} -->\n<div class=\"wp-block-group alignfull has-text-color has-background\" id=\"request-proposal\" style=\"color:#0f172a;background-color:#f1f5f9;padding-top:80px;padding-right:24px;padding-bottom:80px;padding-left:24px\"><!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"48px\",\"left\":\"48px\"}}}} -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"width\":\"45%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:45%\"><!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"13px\",\"fontWeight\":\"700\",\"letterSpacing\":\"0.08em\"},\"color\":{\"text\":\"#ea580c\"}}} -->\n<p class=\"has-text-color\" style=\"color:#ea580c;font-size:13px;font-weight:700;letter-spacing:0.08em\">DIRECT FACTORY ENGINEERING CONSULTATION</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"fontSize\":\"32px\",\"fontWeight\":\"800\"}}} -->\n<h2 class=\"wp-block-heading\" style=\"font-size:32px;font-weight:800\">Request Your Custom Line Proposal &amp; CAD Floor Plan</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#475569\"}}} -->\n<p class=\"has-text-color\" style=\"color:#475569\">Select your target polymers and available workshop length. Our extrusion engineers and sales director will prepare a tailored configuration, output calculation, and itemized quotation within 24 hours.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"style\":{\"typography\":{\"lineHeight\":\"2\"}}} -->\n<ul style=\"line-height:2\" class=\"wp-block-list\"><!-- wp:list-item -->\n<li>✔ <strong>Itemized Hardware Quote</strong> (Extruder, Tank, Laser Gauge, Spooler)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>✔ <strong>Custom 15–25m Workshop CAD Layout</strong> (Straight / L / U-Shape)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>✔ <strong>Turnkey Process Recipe Handover Scope</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>✔ <strong>Live Video Factory Acceptance Test (FAT) Scheduling</strong></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"55%\",\"style\":{\"color\":{\"background\":\"#ffffff\"},\"border\":{\"radius\":\"12px\",\"width\":\"1px\",\"color\":\"#cbd5e1\"},\"spacing\":{\"padding\":{\"top\":\"36px\",\"bottom\":\"36px\",\"left\":\"36px\",\"right\":\"36px\"}}}} -->\n<div class=\"wp-block-column has-border-color has-background\" style=\"border-color:#cbd5e1;border-width:1px;border-radius:12px;background-color:#ffffff;padding-top:36px;padding-right:36px;padding-bottom:36px;padding-left:36px;flex-basis:55%\"><!-- wp:shortcode -->\n[fluentform id=\"1\"]\n<!-- /wp:shortcode --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->', 'Home', '', 'inherit', 'closed', 'closed', '', '1784-revision-v1', '', '', '2026-11-04 12:14:43', '2026-11-04 04:14:43', '', 1784, 'https://hermes-fs.test/?p=1858', 0, 'revision', '', 0);
INSERT INTO `wp_posts` VALUES (1859, 1, '2026-11-04 12:15:06', '2026-11-04 04:15:06', '<!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"background\":\"#0f172a\",\"text\":\"#f8fafc\"},\"spacing\":{\"padding\":{\"top\":\"90px\",\"bottom\":\"90px\",\"left\":\"24px\",\"right\":\"24px\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1280px\"}} -->\n<div class=\"wp-block-group alignfull has-text-color has-background\" style=\"color:#f8fafc;background-color:#0f172a;padding-top:90px;padding-right:24px;padding-bottom:90px;padding-left:24px\"><!-- wp:columns {\"verticalAlignment\":\"center\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"48px\",\"left\":\"48px\"}}}} -->\n<div class=\"wp-block-columns are-vertically-aligned-center\"><!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"60%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:60%\"><!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"13px\",\"fontWeight\":\"700\",\"letterSpacing\":\"0.08em\",\"textTransform\":\"uppercase\"},\"color\":{\"text\":\"#38bdf8\"}}} -->\n<p class=\"has-text-color\" style=\"color:#38bdf8;font-size:13px;font-weight:700;letter-spacing:0.08em;text-transform:uppercase\">INDUSTRIAL 3D FILAMENT EXTRUSION SYSTEMS | 15–25M TURNKEY LINES</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":1,\"style\":{\"typography\":{\"fontSize\":\"44px\",\"lineHeight\":\"1.18\",\"fontWeight\":\"800\"},\"spacing\":{\"margin\":{\"top\":\"12px\",\"bottom\":\"20px\"}}}} -->\n<h1 class=\"wp-block-heading\" style=\"margin-top:12px;margin-bottom:20px;font-size:44px;font-weight:800;line-height:1.18\">Engineered for ±0.02mm Diameter Precision. Built for 24/7 Industrial Filament Production.</h1>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"18px\",\"lineHeight\":\"1.65\"},\"color\":{\"text\":\"#cbd5e1\"}}} -->\n<p class=\"has-text-color\" style=\"color:#cbd5e1;font-size:18px;line-height:1.65\">Stop losing margin to ovality, diameter drift, and tangled spools. We manufacture heavy-duty 15–25m filament extrusion lines integrating <strong>in-house CNC-machined screws</strong>, <strong>real-time laser-to-puller closed-loop control</strong>, and <strong>validated polymer processing recipes</strong>—from standard PLA/PETG to ultra-high-temp PEEK.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"style\":{\"spacing\":{\"margin\":{\"top\":\"32px\"}}}} -->\n<div class=\"wp-block-buttons\" style=\"margin-top:32px\"><!-- wp:button {\"style\":{\"color\":{\"background\":\"#ea580c\",\"text\":\"#ffffff\"},\"border\":{\"radius\":\"6px\"},\"typography\":{\"fontSize\":\"16px\",\"fontWeight\":\"600\"},\"spacing\":{\"padding\":{\"top\":\"14px\",\"bottom\":\"14px\",\"left\":\"28px\",\"right\":\"28px\"}}}} -->\n<div class=\"wp-block-button\" style=\"font-size:16px;font-weight:600\"><a class=\"wp-block-button__link has-text-color has-background wp-element-button\" href=\"#request-proposal\" style=\"border-radius:6px;background-color:#ea580c;color:#ffffff;padding-top:14px;padding-right:28px;padding-bottom:14px;padding-left:28px\">Get Custom Line Layout &amp; Quote →</a></div>\n<!-- /wp:button -->\n\n<!-- wp:button {\"className\":\"is-style-outline\",\"style\":{\"border\":{\"radius\":\"6px\",\"width\":\"1px\"},\"color\":{\"text\":\"#f8fafc\"},\"typography\":{\"fontSize\":\"16px\",\"fontWeight\":\"600\"},\"spacing\":{\"padding\":{\"top\":\"14px\",\"bottom\":\"14px\",\"left\":\"24px\",\"right\":\"24px\"}}}} -->\n<div class=\"wp-block-button is-style-outline\" style=\"font-size:16px;font-weight:600\"><a class=\"wp-block-button__link has-text-color wp-element-button\" href=\"/products/15-25m-industrial-line/\" style=\"border-radius:6px;border-width:1px;color:#f8fafc;padding-top:14px;padding-right:24px;padding-bottom:14px;padding-left:24px\">Explore 15–25m Line Architecture</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"40%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:40%\"><!-- wp:html -->\n<!-- 高质感工程数字孪生监控卡片（完美替代暂缺视频，展现激光闭环实时公差） -->\n      <div style=\"background:rgba(30,41,59,0.85);border:1px solid #334155;border-radius:12px;padding:24px;font-family:\'JetBrains Mono\',monospace;box-shadow:0 20px 50px rgba(0,0,0,0.5);\">\n        <div style=\"display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #334155;padding-bottom:12px;margin-bottom:16px;\">\n          <span style=\"font-size:12px;color:#94a3b8;letter-spacing:0.05em;\">● CLOSED-LOOP PID TELEMETRY</span>\n          <span style=\"background:#065f46;color:#34d399;font-size:11px;padding:3px 8px;border-radius:4px;\">LOCKED ±0.02mm</span>\n        </div>\n        <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:16px;\">\n          <div style=\"background:#0f172a;padding:14px;border-radius:8px;border-left:3px solid #38bdf8;\">\n            <div style=\"font-size:11px;color:#64748b;\">LASER X-AXIS DIA.</div>\n            <div style=\"font-size:24px;font-weight:700;color:#f8fafc;\">1.750 <small style=\"font-size:12px;color:#38bdf8;\">mm</small></div>\n          </div>\n          <div style=\"background:#0f172a;padding:14px;border-radius:8px;border-left:3px solid #38bdf8;\">\n            <div style=\"font-size:11px;color:#64748b;\">LASER Y-AXIS DIA.</div>\n            <div style=\"font-size:24px;font-weight:700;color:#f8fafc;\">1.749 <small style=\"font-size:12px;color:#38bdf8;\">mm</small></div>\n          </div>\n          <div style=\"background:#0f172a;padding:14px;border-radius:8px;border-left:3px solid #22c55e;\">\n            <div style=\"font-size:11px;color:#64748b;\">OVALITY (X-Y)</div>\n            <div style=\"font-size:20px;font-weight:700;color:#22c55e;\">0.008 <small style=\"font-size:12px;\">mm</small></div>\n          </div>\n          <div style=\"background:#0f172a;padding:14px;border-radius:8px;border-left:3px solid #f59e0b;\">\n            <div style=\"font-size:11px;color:#64748b;\">MELT PRESSURE</div>\n            <div style=\"font-size:20px;font-weight:700;color:#f8fafc;\">14.2 <small style=\"font-size:12px;color:#94a3b8;\">±0.1 MPa</small></div>\n          </div>\n        </div>\n        <div style=\"font-size:12px;color:#cbd5e1;line-height:1.6;background:#0f172a;padding:12px;border-radius:6px;\">\n          <div>✔ <strong>Line Footprint:</strong> 15m–25m (Straight / L / U Layout)</div>\n          <div>✔ <strong>Screw &amp; Barrel:</strong> 100% In-House CNC Machined</div>\n          <div>✔ <strong>Turnkey Handover:</strong> Hardware + Plant CAD + Recipes</div>\n        </div>\n      </div>\n<!-- /wp:html --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:html -->\n<!-- 15-25米整线矢量工程蓝图 (Interactive SVG Engineering Schematic Fallback) -->\n  <div style=\"margin-top:48px;background:#1e293b;border:1px solid #334155;border-radius:10px;padding:20px;\">\n    <div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;flex-wrap:wrap;gap:8px;\">\n      <span style=\"font-size:12px;font-family:\'JetBrains Mono\',monospace;color:#38bdf8;font-weight:600;\">[SCHEMATIC BLUEPRINT] 15–25M CLOSED-LOOP INDUSTRIAL EXTRUSION ARCHITECTURE</span>\n      <span style=\"font-size:12px;color:#94a3b8;\">Total Effective Cooling Path: 8m–12m Multi-Stage Laminar Bath</span>\n    </div>\n    <svg viewBox=\"0 0 1100 170\" width=\"100%\" height=\"auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"15 to 25 meter 3D filament extrusion line technical schematic diagram\">\n      <rect width=\"1100\" height=\"170\" rx=\"6\" fill=\"#0f172a\"/>\n      <!-- 网格背景线 -->\n      <line x1=\"0\" y1=\"40\" x2=\"1100\" y2=\"40\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n      <line x1=\"0\" y1=\"85\" x2=\"1100\" y2=\"85\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n      <line x1=\"0\" y1=\"130\" x2=\"1100\" y2=\"130\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n      <!-- 耗材主线 (Filament Path) -->\n      <line x1=\"210\" y1=\"85\" x2=\"960\" y2=\"85\" stroke=\"#ea580c\" stroke-width=\"3\" stroke-dasharray=\"6,3\"/>\n      <!-- 1. 主挤出机 -->\n      <rect x=\"20\" y1=\"45\" y=\"45\" width=\"190\" height=\"75\" rx=\"4\" fill=\"#1e293b\" stroke=\"#38bdf8\" stroke-width=\"2\"/>\n      <text x=\"32\" y=\"70\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">01. CNC EXTRUDER</text>\n      <text x=\"32\" y=\"90\" fill=\"#f8fafc\" font-family=\"sans-serif\" font-size=\"11\">Barrier Screw 45/65mm</text>\n      <text x=\"32\" y=\"106\" fill=\"#94a3b8\" font-family=\"monospace\" font-size=\"10\">Dehumidifier &lt; 50ppm</text>\n      <!-- 2. 多段恒温冷却水槽 -->\n      <rect x=\"250\" y=\"50\" width=\"330\" height=\"65\" rx=\"4\" fill=\"#0c4a6e\" stroke=\"#0284c7\" stroke-width=\"2\"/>\n      <text x=\"265\" y=\"73\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">02. MULTI-STAGE LAMINAR BATH (8-12M)</text>\n      <text x=\"265\" y=\"92\" fill=\"#e0f2fe\" font-family=\"sans-serif\" font-size=\"11\">Zone A (55°C) → Zone B (40°C) → Zone C (25°C)</text>\n      <text x=\"265\" y=\"107\" fill=\"#7dd3fc\" font-family=\"monospace\" font-size=\"10\">Zero Ovality &amp; Zero Internal Voids</text>\n      <!-- 3. 双轴激光测径仪 -->\n      <rect x=\"615\" y=\"45\" width=\"130\" height=\"75\" rx=\"4\" fill=\"#1e293b\" stroke=\"#22c55e\" stroke-width=\"2\"/>\n      <text x=\"625\" y=\"70\" fill=\"#22c55e\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">03. LASER GAUGE</text>\n      <text x=\"625\" y=\"88\" fill=\"#f8fafc\" font-family=\"sans-serif\" font-size=\"11\">X/Y Dual-Axis</text>\n      <text x=\"625\" y=\"105\" fill=\"#4ade80\" font-family=\"monospace\" font-size=\"10\">±0.02mm Check</text>\n      <!-- 4. 伺服牵引机 -->\n      <rect x=\"780\" y=\"45\" width=\"130\" height=\"75\" rx=\"4\" fill=\"#1e293b\" stroke=\"#22c55e\" stroke-width=\"2\"/>\n      <text x=\"790\" y=\"70\" fill=\"#22c55e\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">04. SERVO PULLER</text>\n      <text x=\"790\" y=\"88\" fill=\"#f8fafc\" font-family=\"sans-serif\" font-size=\"11\">PID Sync Drive</text>\n      <text x=\"790\" y=\"105\" fill=\"#94a3b8\" font-family=\"monospace\" font-size=\"10\">&lt;10ms Response</text>\n      <!-- PID 闭环反馈连线 -->\n      <path d=\"M 680 120 L 680 150 L 845 150 L 845 120\" fill=\"none\" stroke=\"#22c55e\" stroke-width=\"2\" stroke-dasharray=\"4,4\"/>\n      <text x=\"705\" y=\"144\" fill=\"#4ade80\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">⇄ REAL-TIME PID CLOSED-LOOP</text>\n      <!-- 5. 双工位自动收卷机 -->\n      <rect x=\"945\" y=\"45\" width=\"135\" height=\"75\" rx=\"4\" fill=\"#1e293b\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n      <text x=\"955\" y=\"70\" fill=\"#f59e0b\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">05. DUAL SPOOLER</text>\n      <text x=\"955\" y=\"88\" fill=\"#f8fafc\" font-family=\"sans-serif\" font-size=\"11\">Servo Neat Wind</text>\n      <text x=\"955\" y=\"105\" fill=\"#fcd34d\" font-family=\"monospace\" font-size=\"10\">Auto Changeover</text>\n    </svg>\n  </div>\n<!-- /wp:html --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"background\":\"#ffffff\",\"text\":\"#0f172a\"},\"spacing\":{\"padding\":{\"top\":\"80px\",\"bottom\":\"80px\",\"left\":\"24px\",\"right\":\"24px\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1280px\"}} -->\n<div class=\"wp-block-group alignfull has-text-color has-background\" style=\"color:#0f172a;background-color:#ffffff;padding-top:80px;padding-right:24px;padding-bottom:80px;padding-left:24px\"><!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"13px\",\"fontWeight\":\"700\",\"letterSpacing\":\"0.08em\",\"textTransform\":\"uppercase\",\"textAlign\":\"center\"},\"color\":{\"text\":\"#0284c7\"}}} -->\n<p class=\"has-text-align-center has-text-color\" style=\"color:#0284c7;font-size:13px;font-weight:700;letter-spacing:0.08em;text-transform:uppercase\">APPLICATION-SPECIFIC EXTRUSION ARCHITECTURE</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"fontSize\":\"36px\",\"fontWeight\":\"800\",\"textAlign\":\"center\"},\"spacing\":{\"margin\":{\"top\":\"8px\",\"bottom\":\"16px\"}}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\" style=\"margin-top:8px;margin-bottom:16px;font-size:36px;font-weight:800\">Choose Your Production Line by Polymer Chemistry</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#475569\"},\"typography\":{\"fontSize\":\"17px\",\"textAlign\":\"center\"},\"spacing\":{\"margin\":{\"bottom\":\"48px\"}}}} -->\n<p class=\"has-text-align-center has-text-color\" style=\"color:#475569;margin-bottom:48px;font-size:17px\">Different polymers demand fundamentally different screw compression ratios, shear profiles, and cooling thermodynamics. We engineer material-dedicated production lines.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"28px\",\"left\":\"28px\"}}}} -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"style\":{\"border\":{\"width\":\"1px\",\"color\":\"#e2e8f0\",\"radius\":\"12px\"},\"spacing\":{\"padding\":{\"top\":\"32px\",\"bottom\":\"32px\",\"left\":\"28px\",\"right\":\"28px\"}},\"color\":{\"background\":\"#f8fafc\"}}} -->\n<div class=\"wp-block-column has-border-color has-background\" style=\"border-color:#e2e8f0;border-width:1px;border-radius:12px;background-color:#f8fafc;padding-top:32px;padding-right:28px;padding-bottom:32px;padding-left:28px\"><!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"12px\",\"fontWeight\":\"700\"},\"color\":{\"text\":\"#0284c7\"}}} -->\n<p class=\"has-text-color\" style=\"color:#0284c7;font-size:12px;font-weight:700\">180°C – 260°C | HIGH-OUTPUT BIO-POLYMERS</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"22px\",\"fontWeight\":\"700\"}}} -->\n<h3 class=\"wp-block-heading\" style=\"font-size:22px;font-weight:700\">PLA &amp; PETG High-Speed Extrusion Line</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#475569\"},\"typography\":{\"fontSize\":\"15px\",\"lineHeight\":\"1.6\"}}} -->\n<p class=\"has-text-color\" style=\"color:#475569;font-size:15px;line-height:1.6\">Optimized with a low-shear barrier screw to prevent molecular degradation and yellowing. Triple-stage gradient constant-temperature water bath eliminates brittle PETG filament syndrome.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"style\":{\"typography\":{\"fontSize\":\"14px\",\"lineHeight\":\"1.8\"}}} -->\n<ul style=\"font-size:14px;line-height:1.8\" class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>Materials:</strong> PLA, PLA+, PETG, Wood/CF-PLA</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Output:</strong> 12 – 30 kg/h (45mm / 65mm Screw)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Tolerance:</strong> 1.75mm / 2.85mm ±0.02mm</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"top\":\"20px\"}},\"typography\":{\"fontWeight\":\"700\"}}} -->\n<p style=\"margin-top:20px;font-weight:700\"><a href=\"/products/pla-petg-filament-extrusion-line/\">Explore PLA/PETG Line Specs →</a></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"border\":{\"width\":\"1px\",\"color\":\"#e2e8f0\",\"radius\":\"12px\"},\"spacing\":{\"padding\":{\"top\":\"32px\",\"bottom\":\"32px\",\"left\":\"28px\",\"right\":\"28px\"}},\"color\":{\"background\":\"#f8fafc\"}}} -->\n<div class=\"wp-block-column has-border-color has-background\" style=\"border-color:#e2e8f0;border-width:1px;border-radius:12px;background-color:#f8fafc;padding-top:32px;padding-right:28px;padding-bottom:32px;padding-left:28px\"><!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"12px\",\"fontWeight\":\"700\"},\"color\":{\"text\":\"#ea580c\"}}} -->\n<p class=\"has-text-color\" style=\"color:#ea580c;font-size:12px;font-weight:700\">220°C – 350°C | SHRINKAGE &amp; VENTING CONTROL</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"22px\",\"fontWeight\":\"700\"}}} -->\n<h3 class=\"wp-block-heading\" style=\"font-size:22px;font-weight:700\">ABS, HIPS &amp; Engineering Plastic Line</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#475569\"},\"typography\":{\"fontSize\":\"15px\",\"lineHeight\":\"1.6\"}}} -->\n<p class=\"has-text-color\" style=\"color:#475569;font-size:15px;line-height:1.6\">Engineered to conquer moisture sensitivity, styrene volatiles, and thermal shrinkage. Features precision degassing zones and thermally insulated annealing baths for zero micro-bubbles.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"style\":{\"typography\":{\"fontSize\":\"14px\",\"lineHeight\":\"1.8\"}}} -->\n<ul style=\"font-size:14px;line-height:1.8\" class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>Materials:</strong> ABS, ASA, HIPS, PC, PA (Nylon), TPU</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Output:</strong> 10 – 25 kg/h Continuous Run</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Cooling:</strong> Insulated Multi-Zone Thermal Bath</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"top\":\"20px\"}},\"typography\":{\"fontWeight\":\"700\"}}} -->\n<p style=\"margin-top:20px;font-weight:700\"><a href=\"/products/abs-hips-filament-extrusion-line/\">Explore ABS/HIPS Line Specs →</a></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"border\":{\"width\":\"1px\",\"color\":\"#e2e8f0\",\"radius\":\"12px\"},\"spacing\":{\"padding\":{\"top\":\"32px\",\"bottom\":\"32px\",\"left\":\"28px\",\"right\":\"28px\"}},\"color\":{\"background\":\"#f8fafc\"}}} -->\n<div class=\"wp-block-column has-border-color has-background\" style=\"border-color:#e2e8f0;border-width:1px;border-radius:12px;background-color:#f8fafc;padding-top:32px;padding-right:28px;padding-bottom:32px;padding-left:28px\"><!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"12px\",\"fontWeight\":\"700\"},\"color\":{\"text\":\"#dc2626\"}}} -->\n<p class=\"has-text-color\" style=\"color:#dc2626;font-size:12px;font-weight:700\">380°C – 500°C | AEROSPACE &amp; MEDICAL GRADE</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"22px\",\"fontWeight\":\"700\"}}} -->\n<h3 class=\"wp-block-heading\" style=\"font-size:22px;font-weight:700\">PEEK &amp; Ultra-High-Temp Polymer Line</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#475569\"},\"typography\":{\"fontSize\":\"15px\",\"lineHeight\":\"1.6\"}}} -->\n<p class=\"has-text-color\" style=\"color:#475569;font-size:15px;line-height:1.6\">Built for extreme thermal stability up to 500°C. Utilizes wear-resistant bimetallic barrels, high-torque servo drives, and inline crystallization ovens with minimal raw resin waste.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"style\":{\"typography\":{\"fontSize\":\"14px\",\"lineHeight\":\"1.8\"}}} -->\n<ul style=\"font-size:14px;line-height:1.8\" class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>Materials:</strong> PEEK, PEKK, PEI (Ultem), PPSU, CF-PEEK</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Barrel:</strong> Bimetallic HRC 65 + SSR PID ±0.5°C</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>ROI Advantage:</strong> Low-Purge Volume Die Design</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"top\":\"20px\"}},\"typography\":{\"fontWeight\":\"700\"}}} -->\n<p style=\"margin-top:20px;font-weight:700\"><a href=\"/products/peek-high-temp-filament-line/\">Explore PEEK High-Temp Specs →</a></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"background\":\"#f1f5f9\",\"text\":\"#0f172a\"},\"spacing\":{\"padding\":{\"top\":\"80px\",\"bottom\":\"80px\",\"left\":\"24px\",\"right\":\"24px\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1280px\"},\"anchor\":\"request-proposal\"} -->\n<div class=\"wp-block-group alignfull has-text-color has-background\" id=\"request-proposal\" style=\"color:#0f172a;background-color:#f1f5f9;padding-top:80px;padding-right:24px;padding-bottom:80px;padding-left:24px\"><!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"48px\",\"left\":\"48px\"}}}} -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"width\":\"45%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:45%\"><!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"13px\",\"fontWeight\":\"700\",\"letterSpacing\":\"0.08em\"},\"color\":{\"text\":\"#ea580c\"}}} -->\n<p class=\"has-text-color\" style=\"color:#ea580c;font-size:13px;font-weight:700;letter-spacing:0.08em\">DIRECT FACTORY ENGINEERING CONSULTATION</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"fontSize\":\"32px\",\"fontWeight\":\"800\"}}} -->\n<h2 class=\"wp-block-heading\" style=\"font-size:32px;font-weight:800\">Request Your Custom Line Proposal &amp; CAD Floor Plan</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#475569\"}}} -->\n<p class=\"has-text-color\" style=\"color:#475569\">Select your target polymers and available workshop length. Our extrusion engineers and sales director will prepare a tailored configuration, output calculation, and itemized quotation within 24 hours.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"style\":{\"typography\":{\"lineHeight\":\"2\"}}} -->\n<ul style=\"line-height:2\" class=\"wp-block-list\"><!-- wp:list-item -->\n<li>✔ <strong>Itemized Hardware Quote</strong> (Extruder, Tank, Laser Gauge, Spooler)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>✔ <strong>Custom 15–25m Workshop CAD Layout</strong> (Straight / L / U-Shape)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>✔ <strong>Turnkey Process Recipe Handover Scope</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>✔ <strong>Live Video Factory Acceptance Test (FAT) Scheduling</strong></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"55%\",\"style\":{\"color\":{\"background\":\"#ffffff\"},\"border\":{\"radius\":\"12px\",\"width\":\"1px\",\"color\":\"#cbd5e1\"},\"spacing\":{\"padding\":{\"top\":\"36px\",\"bottom\":\"36px\",\"left\":\"36px\",\"right\":\"36px\"}}}} -->\n<div class=\"wp-block-column has-border-color has-background\" style=\"border-color:#cbd5e1;border-width:1px;border-radius:12px;background-color:#ffffff;padding-top:36px;padding-right:36px;padding-bottom:36px;padding-left:36px;flex-basis:55%\"><!-- wp:shortcode -->\n[fluentform id=\"1\"]\n<!-- /wp:shortcode --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->', 'Home', '', 'inherit', 'closed', 'closed', '', '1784-revision-v1', '', '', '2026-11-04 12:15:06', '2026-11-04 04:15:06', '', 1784, 'https://hermes-fs.test/?p=1859', 0, 'revision', '', 0);
INSERT INTO `wp_posts` VALUES (1860, 1, '2026-11-04 12:16:58', '2026-11-04 04:16:58', '<!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"background\":\"#0f172a\",\"text\":\"#f8fafc\"},\"spacing\":{\"padding\":{\"top\":\"90px\",\"bottom\":\"90px\",\"left\":\"24px\",\"right\":\"24px\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1280px\"}} -->\n<div class=\"wp-block-group alignfull has-text-color has-background\" style=\"color:#f8fafc;background-color:#0f172a;padding-top:90px;padding-right:24px;padding-bottom:90px;padding-left:24px\"><!-- wp:columns {\"verticalAlignment\":\"center\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"48px\",\"left\":\"48px\"},\"padding\":{\"top\":\"0\"}}}} -->\n<div class=\"wp-block-columns are-vertically-aligned-center\" style=\"padding-top:0\"><!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"60%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:60%\"><!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"13px\",\"fontWeight\":\"700\",\"letterSpacing\":\"0.08em\",\"textTransform\":\"uppercase\"},\"color\":{\"text\":\"#38bdf8\"}}} -->\n<p class=\"has-text-color\" style=\"color:#38bdf8;font-size:13px;font-weight:700;letter-spacing:0.08em;text-transform:uppercase\">INDUSTRIAL 3D FILAMENT EXTRUSION SYSTEMS | 15–25M TURNKEY LINES</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":1,\"style\":{\"typography\":{\"fontSize\":\"44px\",\"lineHeight\":\"1.18\",\"fontWeight\":\"800\"},\"spacing\":{\"margin\":{\"top\":\"12px\",\"bottom\":\"20px\"}}}} -->\n<h1 class=\"wp-block-heading\" style=\"margin-top:12px;margin-bottom:20px;font-size:44px;font-weight:800;line-height:1.18\">Engineered for ±0.02mm Diameter Precision. Built for 24/7 Industrial Filament Production.</h1>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"18px\",\"lineHeight\":\"1.65\"},\"color\":{\"text\":\"#cbd5e1\"}}} -->\n<p class=\"has-text-color\" style=\"color:#cbd5e1;font-size:18px;line-height:1.65\">Stop losing margin to ovality, diameter drift, and tangled spools. We manufacture heavy-duty 15–25m filament extrusion lines integrating <strong>in-house CNC-machined screws</strong>, <strong>real-time laser-to-puller closed-loop control</strong>, and <strong>validated polymer processing recipes</strong>—from standard PLA/PETG to ultra-high-temp PEEK.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"style\":{\"spacing\":{\"margin\":{\"top\":\"32px\"}}}} -->\n<div class=\"wp-block-buttons\" style=\"margin-top:32px\"><!-- wp:button {\"style\":{\"color\":{\"background\":\"#ea580c\",\"text\":\"#ffffff\"},\"border\":{\"radius\":\"6px\"},\"typography\":{\"fontSize\":\"16px\",\"fontWeight\":\"600\"},\"spacing\":{\"padding\":{\"top\":\"14px\",\"bottom\":\"14px\",\"left\":\"28px\",\"right\":\"28px\"}}}} -->\n<div class=\"wp-block-button\" style=\"font-size:16px;font-weight:600\"><a class=\"wp-block-button__link has-text-color has-background wp-element-button\" href=\"#request-proposal\" style=\"border-radius:6px;background-color:#ea580c;color:#ffffff;padding-top:14px;padding-right:28px;padding-bottom:14px;padding-left:28px\">Get Custom Line Layout &amp; Quote →</a></div>\n<!-- /wp:button -->\n\n<!-- wp:button {\"className\":\"is-style-outline\",\"style\":{\"border\":{\"radius\":\"6px\",\"width\":\"1px\"},\"color\":{\"text\":\"#f8fafc\"},\"typography\":{\"fontSize\":\"16px\",\"fontWeight\":\"600\"},\"spacing\":{\"padding\":{\"top\":\"14px\",\"bottom\":\"14px\",\"left\":\"24px\",\"right\":\"24px\"}}}} -->\n<div class=\"wp-block-button is-style-outline\" style=\"font-size:16px;font-weight:600\"><a class=\"wp-block-button__link has-text-color wp-element-button\" href=\"/products/15-25m-industrial-line/\" style=\"border-radius:6px;border-width:1px;color:#f8fafc;padding-top:14px;padding-right:24px;padding-bottom:14px;padding-left:24px\">Explore 15–25m Line Architecture</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"40%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:40%\"><!-- wp:html -->\n<!-- 高质感工程数字孪生监控卡片（完美替代暂缺视频，展现激光闭环实时公差） -->\n      <div style=\"background:rgba(30,41,59,0.85);border:1px solid #334155;border-radius:12px;padding:24px;font-family:\'JetBrains Mono\',monospace;box-shadow:0 20px 50px rgba(0,0,0,0.5);\">\n        <div style=\"display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #334155;padding-bottom:12px;margin-bottom:16px;\">\n          <span style=\"font-size:12px;color:#94a3b8;letter-spacing:0.05em;\">● CLOSED-LOOP PID TELEMETRY</span>\n          <span style=\"background:#065f46;color:#34d399;font-size:11px;padding:3px 8px;border-radius:4px;\">LOCKED ±0.02mm</span>\n        </div>\n        <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:16px;\">\n          <div style=\"background:#0f172a;padding:14px;border-radius:8px;border-left:3px solid #38bdf8;\">\n            <div style=\"font-size:11px;color:#64748b;\">LASER X-AXIS DIA.</div>\n            <div style=\"font-size:24px;font-weight:700;color:#f8fafc;\">1.750 <small style=\"font-size:12px;color:#38bdf8;\">mm</small></div>\n          </div>\n          <div style=\"background:#0f172a;padding:14px;border-radius:8px;border-left:3px solid #38bdf8;\">\n            <div style=\"font-size:11px;color:#64748b;\">LASER Y-AXIS DIA.</div>\n            <div style=\"font-size:24px;font-weight:700;color:#f8fafc;\">1.749 <small style=\"font-size:12px;color:#38bdf8;\">mm</small></div>\n          </div>\n          <div style=\"background:#0f172a;padding:14px;border-radius:8px;border-left:3px solid #22c55e;\">\n            <div style=\"font-size:11px;color:#64748b;\">OVALITY (X-Y)</div>\n            <div style=\"font-size:20px;font-weight:700;color:#22c55e;\">0.008 <small style=\"font-size:12px;\">mm</small></div>\n          </div>\n          <div style=\"background:#0f172a;padding:14px;border-radius:8px;border-left:3px solid #f59e0b;\">\n            <div style=\"font-size:11px;color:#64748b;\">MELT PRESSURE</div>\n            <div style=\"font-size:20px;font-weight:700;color:#f8fafc;\">14.2 <small style=\"font-size:12px;color:#94a3b8;\">±0.1 MPa</small></div>\n          </div>\n        </div>\n        <div style=\"font-size:12px;color:#cbd5e1;line-height:1.6;background:#0f172a;padding:12px;border-radius:6px;\">\n          <div>✔ <strong>Line Footprint:</strong> 15m–25m (Straight / L / U Layout)</div>\n          <div>✔ <strong>Screw &amp; Barrel:</strong> 100% In-House CNC Machined</div>\n          <div>✔ <strong>Turnkey Handover:</strong> Hardware + Plant CAD + Recipes</div>\n        </div>\n      </div>\n<!-- /wp:html --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:html -->\n<!-- 15-25米整线矢量工程蓝图 (Interactive SVG Engineering Schematic Fallback) -->\n  <div style=\"margin-top:48px;background:#1e293b;border:1px solid #334155;border-radius:10px;padding:20px;\">\n    <div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;flex-wrap:wrap;gap:8px;\">\n      <span style=\"font-size:12px;font-family:\'JetBrains Mono\',monospace;color:#38bdf8;font-weight:600;\">[SCHEMATIC BLUEPRINT] 15–25M CLOSED-LOOP INDUSTRIAL EXTRUSION ARCHITECTURE</span>\n      <span style=\"font-size:12px;color:#94a3b8;\">Total Effective Cooling Path: 8m–12m Multi-Stage Laminar Bath</span>\n    </div>\n    <svg viewBox=\"0 0 1100 170\" width=\"100%\" height=\"auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"15 to 25 meter 3D filament extrusion line technical schematic diagram\">\n      <rect width=\"1100\" height=\"170\" rx=\"6\" fill=\"#0f172a\"/>\n      <!-- 网格背景线 -->\n      <line x1=\"0\" y1=\"40\" x2=\"1100\" y2=\"40\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n      <line x1=\"0\" y1=\"85\" x2=\"1100\" y2=\"85\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n      <line x1=\"0\" y1=\"130\" x2=\"1100\" y2=\"130\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n      <!-- 耗材主线 (Filament Path) -->\n      <line x1=\"210\" y1=\"85\" x2=\"960\" y2=\"85\" stroke=\"#ea580c\" stroke-width=\"3\" stroke-dasharray=\"6,3\"/>\n      <!-- 1. 主挤出机 -->\n      <rect x=\"20\" y1=\"45\" y=\"45\" width=\"190\" height=\"75\" rx=\"4\" fill=\"#1e293b\" stroke=\"#38bdf8\" stroke-width=\"2\"/>\n      <text x=\"32\" y=\"70\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">01. CNC EXTRUDER</text>\n      <text x=\"32\" y=\"90\" fill=\"#f8fafc\" font-family=\"sans-serif\" font-size=\"11\">Barrier Screw 45/65mm</text>\n      <text x=\"32\" y=\"106\" fill=\"#94a3b8\" font-family=\"monospace\" font-size=\"10\">Dehumidifier &lt; 50ppm</text>\n      <!-- 2. 多段恒温冷却水槽 -->\n      <rect x=\"250\" y=\"50\" width=\"330\" height=\"65\" rx=\"4\" fill=\"#0c4a6e\" stroke=\"#0284c7\" stroke-width=\"2\"/>\n      <text x=\"265\" y=\"73\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">02. MULTI-STAGE LAMINAR BATH (8-12M)</text>\n      <text x=\"265\" y=\"92\" fill=\"#e0f2fe\" font-family=\"sans-serif\" font-size=\"11\">Zone A (55°C) → Zone B (40°C) → Zone C (25°C)</text>\n      <text x=\"265\" y=\"107\" fill=\"#7dd3fc\" font-family=\"monospace\" font-size=\"10\">Zero Ovality &amp; Zero Internal Voids</text>\n      <!-- 3. 双轴激光测径仪 -->\n      <rect x=\"615\" y=\"45\" width=\"130\" height=\"75\" rx=\"4\" fill=\"#1e293b\" stroke=\"#22c55e\" stroke-width=\"2\"/>\n      <text x=\"625\" y=\"70\" fill=\"#22c55e\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">03. LASER GAUGE</text>\n      <text x=\"625\" y=\"88\" fill=\"#f8fafc\" font-family=\"sans-serif\" font-size=\"11\">X/Y Dual-Axis</text>\n      <text x=\"625\" y=\"105\" fill=\"#4ade80\" font-family=\"monospace\" font-size=\"10\">±0.02mm Check</text>\n      <!-- 4. 伺服牵引机 -->\n      <rect x=\"780\" y=\"45\" width=\"130\" height=\"75\" rx=\"4\" fill=\"#1e293b\" stroke=\"#22c55e\" stroke-width=\"2\"/>\n      <text x=\"790\" y=\"70\" fill=\"#22c55e\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">04. SERVO PULLER</text>\n      <text x=\"790\" y=\"88\" fill=\"#f8fafc\" font-family=\"sans-serif\" font-size=\"11\">PID Sync Drive</text>\n      <text x=\"790\" y=\"105\" fill=\"#94a3b8\" font-family=\"monospace\" font-size=\"10\">&lt;10ms Response</text>\n      <!-- PID 闭环反馈连线 -->\n      <path d=\"M 680 120 L 680 150 L 845 150 L 845 120\" fill=\"none\" stroke=\"#22c55e\" stroke-width=\"2\" stroke-dasharray=\"4,4\"/>\n      <text x=\"705\" y=\"144\" fill=\"#4ade80\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">⇄ REAL-TIME PID CLOSED-LOOP</text>\n      <!-- 5. 双工位自动收卷机 -->\n      <rect x=\"945\" y=\"45\" width=\"135\" height=\"75\" rx=\"4\" fill=\"#1e293b\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n      <text x=\"955\" y=\"70\" fill=\"#f59e0b\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">05. DUAL SPOOLER</text>\n      <text x=\"955\" y=\"88\" fill=\"#f8fafc\" font-family=\"sans-serif\" font-size=\"11\">Servo Neat Wind</text>\n      <text x=\"955\" y=\"105\" fill=\"#fcd34d\" font-family=\"monospace\" font-size=\"10\">Auto Changeover</text>\n    </svg>\n  </div>\n<!-- /wp:html --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"background\":\"#ffffff\",\"text\":\"#0f172a\"},\"spacing\":{\"padding\":{\"top\":\"80px\",\"bottom\":\"80px\",\"left\":\"24px\",\"right\":\"24px\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1280px\"}} -->\n<div class=\"wp-block-group alignfull has-text-color has-background\" style=\"color:#0f172a;background-color:#ffffff;padding-top:80px;padding-right:24px;padding-bottom:80px;padding-left:24px\"><!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"13px\",\"fontWeight\":\"700\",\"letterSpacing\":\"0.08em\",\"textTransform\":\"uppercase\",\"textAlign\":\"center\"},\"color\":{\"text\":\"#0284c7\"}}} -->\n<p class=\"has-text-align-center has-text-color\" style=\"color:#0284c7;font-size:13px;font-weight:700;letter-spacing:0.08em;text-transform:uppercase\">APPLICATION-SPECIFIC EXTRUSION ARCHITECTURE</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"fontSize\":\"36px\",\"fontWeight\":\"800\",\"textAlign\":\"center\"},\"spacing\":{\"margin\":{\"top\":\"8px\",\"bottom\":\"16px\"}}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\" style=\"margin-top:8px;margin-bottom:16px;font-size:36px;font-weight:800\">Choose Your Production Line by Polymer Chemistry</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#475569\"},\"typography\":{\"fontSize\":\"17px\",\"textAlign\":\"center\"},\"spacing\":{\"margin\":{\"bottom\":\"48px\"}}}} -->\n<p class=\"has-text-align-center has-text-color\" style=\"color:#475569;margin-bottom:48px;font-size:17px\">Different polymers demand fundamentally different screw compression ratios, shear profiles, and cooling thermodynamics. We engineer material-dedicated production lines.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"28px\",\"left\":\"28px\"}}}} -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"style\":{\"border\":{\"width\":\"1px\",\"color\":\"#e2e8f0\",\"radius\":\"12px\"},\"spacing\":{\"padding\":{\"top\":\"32px\",\"bottom\":\"32px\",\"left\":\"28px\",\"right\":\"28px\"}},\"color\":{\"background\":\"#f8fafc\"}}} -->\n<div class=\"wp-block-column has-border-color has-background\" style=\"border-color:#e2e8f0;border-width:1px;border-radius:12px;background-color:#f8fafc;padding-top:32px;padding-right:28px;padding-bottom:32px;padding-left:28px\"><!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"12px\",\"fontWeight\":\"700\"},\"color\":{\"text\":\"#0284c7\"}}} -->\n<p class=\"has-text-color\" style=\"color:#0284c7;font-size:12px;font-weight:700\">180°C – 260°C | HIGH-OUTPUT BIO-POLYMERS</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"22px\",\"fontWeight\":\"700\"}}} -->\n<h3 class=\"wp-block-heading\" style=\"font-size:22px;font-weight:700\">PLA &amp; PETG High-Speed Extrusion Line</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#475569\"},\"typography\":{\"fontSize\":\"15px\",\"lineHeight\":\"1.6\"}}} -->\n<p class=\"has-text-color\" style=\"color:#475569;font-size:15px;line-height:1.6\">Optimized with a low-shear barrier screw to prevent molecular degradation and yellowing. Triple-stage gradient constant-temperature water bath eliminates brittle PETG filament syndrome.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"style\":{\"typography\":{\"fontSize\":\"14px\",\"lineHeight\":\"1.8\"}}} -->\n<ul style=\"font-size:14px;line-height:1.8\" class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>Materials:</strong> PLA, PLA+, PETG, Wood/CF-PLA</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Output:</strong> 12 – 30 kg/h (45mm / 65mm Screw)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Tolerance:</strong> 1.75mm / 2.85mm ±0.02mm</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"top\":\"20px\"}},\"typography\":{\"fontWeight\":\"700\"}}} -->\n<p style=\"margin-top:20px;font-weight:700\"><a href=\"/products/pla-petg-filament-extrusion-line/\">Explore PLA/PETG Line Specs →</a></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"border\":{\"width\":\"1px\",\"color\":\"#e2e8f0\",\"radius\":\"12px\"},\"spacing\":{\"padding\":{\"top\":\"32px\",\"bottom\":\"32px\",\"left\":\"28px\",\"right\":\"28px\"}},\"color\":{\"background\":\"#f8fafc\"}}} -->\n<div class=\"wp-block-column has-border-color has-background\" style=\"border-color:#e2e8f0;border-width:1px;border-radius:12px;background-color:#f8fafc;padding-top:32px;padding-right:28px;padding-bottom:32px;padding-left:28px\"><!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"12px\",\"fontWeight\":\"700\"},\"color\":{\"text\":\"#ea580c\"}}} -->\n<p class=\"has-text-color\" style=\"color:#ea580c;font-size:12px;font-weight:700\">220°C – 350°C | SHRINKAGE &amp; VENTING CONTROL</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"22px\",\"fontWeight\":\"700\"}}} -->\n<h3 class=\"wp-block-heading\" style=\"font-size:22px;font-weight:700\">ABS, HIPS &amp; Engineering Plastic Line</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#475569\"},\"typography\":{\"fontSize\":\"15px\",\"lineHeight\":\"1.6\"}}} -->\n<p class=\"has-text-color\" style=\"color:#475569;font-size:15px;line-height:1.6\">Engineered to conquer moisture sensitivity, styrene volatiles, and thermal shrinkage. Features precision degassing zones and thermally insulated annealing baths for zero micro-bubbles.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"style\":{\"typography\":{\"fontSize\":\"14px\",\"lineHeight\":\"1.8\"}}} -->\n<ul style=\"font-size:14px;line-height:1.8\" class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>Materials:</strong> ABS, ASA, HIPS, PC, PA (Nylon), TPU</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Output:</strong> 10 – 25 kg/h Continuous Run</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Cooling:</strong> Insulated Multi-Zone Thermal Bath</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"top\":\"20px\"}},\"typography\":{\"fontWeight\":\"700\"}}} -->\n<p style=\"margin-top:20px;font-weight:700\"><a href=\"/products/abs-hips-filament-extrusion-line/\">Explore ABS/HIPS Line Specs →</a></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"border\":{\"width\":\"1px\",\"color\":\"#e2e8f0\",\"radius\":\"12px\"},\"spacing\":{\"padding\":{\"top\":\"32px\",\"bottom\":\"32px\",\"left\":\"28px\",\"right\":\"28px\"}},\"color\":{\"background\":\"#f8fafc\"}}} -->\n<div class=\"wp-block-column has-border-color has-background\" style=\"border-color:#e2e8f0;border-width:1px;border-radius:12px;background-color:#f8fafc;padding-top:32px;padding-right:28px;padding-bottom:32px;padding-left:28px\"><!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"12px\",\"fontWeight\":\"700\"},\"color\":{\"text\":\"#dc2626\"}}} -->\n<p class=\"has-text-color\" style=\"color:#dc2626;font-size:12px;font-weight:700\">380°C – 500°C | AEROSPACE &amp; MEDICAL GRADE</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"22px\",\"fontWeight\":\"700\"}}} -->\n<h3 class=\"wp-block-heading\" style=\"font-size:22px;font-weight:700\">PEEK &amp; Ultra-High-Temp Polymer Line</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#475569\"},\"typography\":{\"fontSize\":\"15px\",\"lineHeight\":\"1.6\"}}} -->\n<p class=\"has-text-color\" style=\"color:#475569;font-size:15px;line-height:1.6\">Built for extreme thermal stability up to 500°C. Utilizes wear-resistant bimetallic barrels, high-torque servo drives, and inline crystallization ovens with minimal raw resin waste.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"style\":{\"typography\":{\"fontSize\":\"14px\",\"lineHeight\":\"1.8\"}}} -->\n<ul style=\"font-size:14px;line-height:1.8\" class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>Materials:</strong> PEEK, PEKK, PEI (Ultem), PPSU, CF-PEEK</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Barrel:</strong> Bimetallic HRC 65 + SSR PID ±0.5°C</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>ROI Advantage:</strong> Low-Purge Volume Die Design</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"top\":\"20px\"}},\"typography\":{\"fontWeight\":\"700\"}}} -->\n<p style=\"margin-top:20px;font-weight:700\"><a href=\"/products/peek-high-temp-filament-line/\">Explore PEEK High-Temp Specs →</a></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"background\":\"#f1f5f9\",\"text\":\"#0f172a\"},\"spacing\":{\"padding\":{\"top\":\"80px\",\"bottom\":\"80px\",\"left\":\"24px\",\"right\":\"24px\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1280px\"},\"anchor\":\"request-proposal\"} -->\n<div class=\"wp-block-group alignfull has-text-color has-background\" id=\"request-proposal\" style=\"color:#0f172a;background-color:#f1f5f9;padding-top:80px;padding-right:24px;padding-bottom:80px;padding-left:24px\"><!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"48px\",\"left\":\"48px\"}}}} -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"width\":\"45%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:45%\"><!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"13px\",\"fontWeight\":\"700\",\"letterSpacing\":\"0.08em\"},\"color\":{\"text\":\"#ea580c\"}}} -->\n<p class=\"has-text-color\" style=\"color:#ea580c;font-size:13px;font-weight:700;letter-spacing:0.08em\">DIRECT FACTORY ENGINEERING CONSULTATION</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"fontSize\":\"32px\",\"fontWeight\":\"800\"}}} -->\n<h2 class=\"wp-block-heading\" style=\"font-size:32px;font-weight:800\">Request Your Custom Line Proposal &amp; CAD Floor Plan</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#475569\"}}} -->\n<p class=\"has-text-color\" style=\"color:#475569\">Select your target polymers and available workshop length. Our extrusion engineers and sales director will prepare a tailored configuration, output calculation, and itemized quotation within 24 hours.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"style\":{\"typography\":{\"lineHeight\":\"2\"}}} -->\n<ul style=\"line-height:2\" class=\"wp-block-list\"><!-- wp:list-item -->\n<li>✔ <strong>Itemized Hardware Quote</strong> (Extruder, Tank, Laser Gauge, Spooler)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>✔ <strong>Custom 15–25m Workshop CAD Layout</strong> (Straight / L / U-Shape)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>✔ <strong>Turnkey Process Recipe Handover Scope</strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>✔ <strong>Live Video Factory Acceptance Test (FAT) Scheduling</strong></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"55%\",\"style\":{\"color\":{\"background\":\"#ffffff\"},\"border\":{\"radius\":\"12px\",\"width\":\"1px\",\"color\":\"#cbd5e1\"},\"spacing\":{\"padding\":{\"top\":\"36px\",\"bottom\":\"36px\",\"left\":\"36px\",\"right\":\"36px\"}}}} -->\n<div class=\"wp-block-column has-border-color has-background\" style=\"border-color:#cbd5e1;border-width:1px;border-radius:12px;background-color:#ffffff;padding-top:36px;padding-right:36px;padding-bottom:36px;padding-left:36px;flex-basis:55%\"><!-- wp:shortcode -->\n[fluentform id=\"1\"]\n<!-- /wp:shortcode --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->', 'Home', '', 'inherit', 'closed', 'closed', '', '1784-revision-v1', '', '', '2026-11-04 12:16:58', '2026-11-04 04:16:58', '', 1784, 'https://hermes-fs.test/?p=1860', 0, 'revision', '', 0);
